def _validate(type_: str, rank: int) -> None:
    """Validate (type, rank) lies in the Cartan-Killing classification.

    Raises ValueError otherwise.
    """
    if not isinstance(type_, str) or len(type_) != 1 or type_ not in _VALID_TYPES:
        raise ValueError(
            f"unknown root-system type {type_!r}; expected one of "
            f"{_VALID_TYPES}"
        )
    if not isinstance(rank, (int, np.integer)) or rank < 1:
        raise ValueError(f"rank must be a positive integer, got {rank!r}")
    if type_ == "A" and rank < 1:
        raise ValueError("A_n requires n >= 1")
    if type_ in ("B", "C") and rank < 2:
        raise ValueError(f"{type_}_n requires n >= 2 (rank=1 collapses to A_1)")
    if type_ == "D" and rank < 3:
        raise ValueError(
            "D_n requires n >= 3 (D_1 is trivial, D_2 = A_1 x A_1 is reducible)"
        )
    if type_ == "E" and rank not in (6, 7, 8):
        raise ValueError(f"E_n only exists for n in (6, 7, 8); got n={rank}")
    if type_ == "F" and rank != 4:
        raise ValueError(f"F_n only exists for n=4; got n={rank}")
    if type_ == "G" and rank != 2:
        raise ValueError(f"G_n only exists for n=2; got n={rank}")

def simple_roots(type_: str, rank: int) -> np.ndarray:
    """Simple roots as rows in standard Euclidean coordinates.

    Reference: Bourbaki Lie IV-VI Plates I-IX.
    """
    _validate(type_, rank)
    return _simple_roots_matrix(type_, rank).copy()

def weyl_group_order(type_: str, rank: int) -> int:
    """Order of the Weyl group W.

    Reference: Humphreys 2.10, Bourbaki Lie IV-VI Plates.
    """
    _validate(type_, rank)
    n = rank
    if type_ == "A":
        return factorial(n + 1)
    if type_ in ("B", "C"):
        return (2 ** n) * factorial(n)
    if type_ == "D":
        return (2 ** (n - 1)) * factorial(n)
    return _EXCEPTIONAL_W[(type_, rank)]

def _coxeter_number(type_: str, rank: int) -> int:
    """Coxeter number h.

    Reference: Humphreys 12.2 / Bourbaki Plates.
    """
    n = rank
    if type_ == "A":
        return n + 1
    if type_ in ("B", "C"):
        return 2 * n
    if type_ == "D":
        return 2 * n - 2
    if type_ == "E":
        return {6: 12, 7: 18, 8: 30}[n]
    if type_ == "F":
        return 12
    if type_ == "G":
        return 6
    raise ValueError(type_)  # pragma: no cover

def dynkin_diagram_string(type_: str, rank: int) -> str:
    """ASCII Dynkin diagram for the irreducible type.

    Each ``o`` is a node, each ``-`` a single bond, ``=>`` and ``<=`` are
    double bonds with arrows pointing toward the short root, ``=>=`` is
    the triple bond used for G_2.

    Reference: Humphreys 11.4, Bourbaki Plates.
    """
    _validate(type_, rank)
    n = rank
    if type_ == "A":
        nodes = "---".join(["o"] * n)
        return f"A_{n}: " + nodes
    if type_ == "B":
        # o---o---...---o=>=o (last two with arrow toward short root)
        if n == 1:
            return f"B_1: o"  # pragma: no cover (validated out)
        prefix = "---".join(["o"] * (n - 1))
        return f"B_{n}: {prefix}=>=o"
    if type_ == "C":
        prefix = "---".join(["o"] * (n - 1))
        return f"C_{n}: {prefix}=<=o"
    if type_ == "D":
        if n < 3:
            return f"D_{n}: o"  # pragma: no cover
        # D_n: chain of n-2 nodes branching to two on the right
        chain = "---".join(["o"] * (n - 2))
        return f"D_{n}: {chain}---o\n          \\\n           o"
    if type_ == "E":
        # E_n: chain o-o-o-... with a branch at the third node
        if n == 6:
            return "E_6: o---o---o---o---o\n             |\n             o"
        if n == 7:
            return "E_7: o---o---o---o---o---o\n             |\n             o"
        if n == 8:
            return "E_8: o---o---o---o---o---o---o\n             |\n             o"
    if type_ == "F":
        return "F_4: o---o=>=o---o"
    if type_ == "G":
        return "G_2: o#=#o"  # triple bond
    raise ValueError(type_)  # pragma: no cover

def is_dominant_weight(weight: Sequence[int], type_: str, rank: int) -> bool:
    """A weight given by its Dynkin labels (coefficients in the
    fundamental-weight basis) is dominant iff all labels are >= 0.

    Reference: Humphreys 13.1.

    Edge: empty or wrong-length input -> ValueError.
    """
    _validate(type_, rank)
    if not isinstance(weight, (list, tuple, np.ndarray)) or len(weight) == 0:
        raise ValueError("weight must be a non-empty sequence")
    if len(weight) != rank:
        raise ValueError(
            f"weight has {len(weight)} components; expected {rank}"
        )
    return all(int(w) >= 0 for w in weight)

def _identity_predictor(rank: int) -> int:
    """Trivial callable bound by the env: receives the predicted rank,
    returns it unchanged. The substrate uses this as the EVAL hook so
    each prediction generates one (binding, evaluation) row pair."""
    return int(rank)

def forward(self, obs):  # noqa: D401
    """Run MLP forward pass; returns raw logits, shape [B, n_actions].

    Accepts a torch tensor of shape [B, obs_dim] or [obs_dim]. The
    latter is unsqueezed to [1, obs_dim] then squeezed back.
    """
    if obs.ndim == 1:
        return self.net(obs.unsqueeze(0)).squeeze(0)
    return self.net(obs)

def _require_galois() -> None:
    if not _HAS_GALOIS:
        raise ImportError(
            "prometheus_math.coding_linear requires the `galois` "
            "package. Install with `pip install galois`."
        )

def _lehmer_poly(n: int) -> List[int]:
    # Reciprocal polynomial of degree n; pads Lehmer's classic to n.
    base = [1, 1, 0, -1, -1, -1, -1, -1, 0, 1, 1]
    if n <= len(base):
        return base[:n + 1] if n + 1 <= len(base) else base
    pad = (n + 1 - len(base)) // 2
    return [1] * pad + base + [1] * (n + 1 - len(base) - pad)

def __post_init__(self) -> None:
    if not isinstance(self.kill_record, KillVector):
        raise TypeError(
            f"kill_record must be a KillVector; got "
            f"{type(self.kill_record).__name__}"
        )
    if not isinstance(self.substrate_version, str) or not self.substrate_version:
        raise ValueError(
            f"substrate_version must be a non-empty string; got "
            f"{self.substrate_version!r}"
        )
    if not isinstance(self.transformation_chain, tuple):
        raise TypeError(
            f"transformation_chain must be a tuple of strings; got "
            f"{type(self.transformation_chain).__name__}"
        )
    for op in self.transformation_chain:
        if not isinstance(op, str):
            raise TypeError(
                f"transformation_chain entries must be strings; got "
                f"{type(op).__name__}"
            )

def _compute_reward_shaped(m_value: float) -> Tuple[float, str]:
    """Continuous reward variant: smooth gradient toward low M.

    Reward = max(0, 50 * (5 - M) / 4) for M in [1.001, 5];
    plus a +50 bonus if M in (1.001, 1.18) (sub-Lehmer);
    cyclotomics (M ≈ 1) still score 0 (sparse anchor).

    The continuous gradient gives the agent a learning signal across
    the entire M-range, not just at band boundaries. This addresses
    the local-optimum trap that the step-reward shape produces.
    """
    if not math.isfinite(m_value):
        return 0.0, "non_finite"
    if m_value < 1.0 - 1e-9:
        return 0.0, "numerical_artifact"
    if m_value < 1.001:
        return 0.0, "cyclotomic"  # sparse anchor stays
    if m_value < 1.18:
        # Sub-Lehmer: large bonus on top of continuous gradient.
        return 50.0 + 50.0 * (5.0 - m_value) / 4.0, "sub_lehmer"
    if m_value < 5.0:
        return 50.0 * (5.0 - m_value) / 4.0, "shaped_continuous"
    return 0.0, "large_m"

def _check_mossinghoff(
    coeffs: List[int], m_value: float
) -> Tuple[Optional[bool], Optional[str]]:
    """Return (is_known, label).  ``is_known=True`` if the polynomial
    matches a Mossinghoff entry by Mahler measure within 1e-5; ``False``
    if it doesn't; ``None`` if the snapshot is unavailable."""
    try:
        from prometheus_math.databases import mahler as _mahler_db
    except Exception:
        return None, None
    # Mossinghoff snapshot is keyed by M-value; do a tolerance check.
    snapshot = getattr(_mahler_db, "MAHLER_TABLE", None)
    if snapshot is None:
        return None, None
    for entry in snapshot:
        try:
            entry_m = float(entry.get("mahler_measure", float("inf")))
        except (TypeError, ValueError):
            continue
        if abs(entry_m - m_value) < 1e-5:
            return True, entry.get("label") or entry.get("name") or "unknown"
    return False, None

def discoveries(self) -> List[EpisodeRecord]:
    """Return all rewarded episodes (sub-Lehmer + Salem cluster)."""
    return list(self._discoveries)

def sub_lehmer_candidates(self) -> List[EpisodeRecord]:
    """Return only sub-Lehmer-candidate episodes that are NOT in the
    Mossinghoff snapshot.  Each one is a hand-verification target."""
    return list(self._sub_lehmer_candidates)

def _evaluate_m(self, member: PopulationMember) -> float:
    """EVAL the Mahler measure of a member through the substrate."""
    if self._kernel is None or self._ext is None:
        raise RuntimeError("env not reset; cannot eval")
    full = member.full(self.degree)
    if all(c == 0 for c in full):
        return float("inf")
    cap = self._kernel.mint_capability("EvalCap")
    try:
        ev = self._ext.EVAL(
            binding_name=self._mm_binding_name,
            binding_version=self._mm_binding_version,
            args=[full],
            cap=cap,
            eval_version=self._n_evals + 1,
        )
        self._n_evals += 1
    except BudgetExceeded:
        return float("inf")
    if not ev.success:
        return float("inf")
    try:
        return float(ev.output_repr)
    except (TypeError, ValueError):
        return float("inf")

def _build_distance_to_target(
    kill_vector: Optional[Any],
    target_band_name: str,
) -> DistanceToTarget:
    """Find the named target-band component in kill_vector and extract margin."""
    if kill_vector is None:
        return DistanceToTarget(value=None, unit=None)
    components = getattr(kill_vector, "components", None)
    if not components:
        return DistanceToTarget(value=None, unit=None)
    for c in components:
        if getattr(c, "falsifier_name", None) == target_band_name:
            margin = getattr(c, "margin", None)
            triggered = getattr(c, "triggered", False)
            # Convention: triggered (in band) → 0.0; not triggered (out of band) → margin
            value = 0.0 if triggered else (None if margin is None else float(margin))
            return DistanceToTarget(
                value=value,
                unit=getattr(c, "margin_unit", None),
                computed_at_dps=getattr(c, "precision_dps", None),
            )
    return DistanceToTarget(value=None, unit=None)

def _build_battery_survival_depth(kill_vector: Optional[Any]) -> BatterySurvivalDepth:
    if kill_vector is None:
        return BatterySurvivalDepth(n_passed=0, n_total=0)
    components = getattr(kill_vector, "components", None)
    if not components:
        return BatterySurvivalDepth(n_passed=0, n_total=0)
    passed: List[str] = []
    failed: List[str] = []
    for c in components:
        name = getattr(c, "falsifier_name", "?")
        if getattr(c, "triggered", False):
            failed.append(name)
        else:
            passed.append(name)
    return BatterySurvivalDepth(
        n_passed=len(passed),
        n_total=len(passed) + len(failed),
        falsifiers_passed=tuple(passed),
        falsifiers_failed=tuple(failed),
    )

def _build_verification_depth(
    *,
    precision_metadata: Optional[Mapping[str, Any]],
    methods_used: Sequence[str],
    stability_aggregate: Optional[Mapping[str, Any]],
    kill_vector: Optional[Any],
) -> VerificationDepth:
    # min_precision_dps from precision_metadata or aggregated from kill_vector
    min_dps: Optional[int] = None
    if precision_metadata and precision_metadata.get("dps") is not None:
        min_dps = int(precision_metadata["dps"])
    elif kill_vector is not None:
        components = getattr(kill_vector, "components", None) or ()
        dps_values = [
            getattr(c, "precision_dps", None)
            for c in components
            if getattr(c, "precision_dps", None) is not None
        ]
        if dps_values:
            min_dps = int(min(dps_values))

    # methods_used: prefer explicit param; fall back to kill_vector aggregation
    methods: Tuple[str, ...] = tuple(sorted(set(methods_used)))
    if not methods and kill_vector is not None:
        components = getattr(kill_vector, "components", None) or ()
        method_set = {
            str(getattr(c, "method", "unknown"))
            for c in components
            if getattr(c, "method", None)
        }
        methods = tuple(sorted(method_set))

    # convergence_summary
    if precision_metadata and precision_metadata.get("convergence"):
        conv_summary = str(precision_metadata["convergence"])
    elif kill_vector is not None:
        components = getattr(kill_vector, "components", None) or ()
        conv_set = {
            str(getattr(c, "convergence_status", "n/a"))
            for c in components
            if getattr(c, "convergence_status", None)
        }
        if not conv_set:
            conv_summary = "n/a"
        elif conv_set == {"converged"}:
            conv_summary = "all_converged"
        elif "failed_max_steps" in conv_set or "nan_returned" in conv_set:
            conv_summary = "some_failed" if "converged" in conv_set else "all_failed"
        else:
            conv_summary = "mixed"
    else:
        conv_summary = "n/a"

    return VerificationDepth(
        min_precision_dps=min_dps,
        methods_used=methods,
        convergence_summary=conv_summary,
        stability_aggregate=dict(stability_aggregate) if stability_aggregate else None,
    )

def _extract_lehmer_smoke_records(rec: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Lehmer brute-force smoke: real M values for the in-band hits."""
    if rec["schema"] != "lehmer_smoke":
        return []
    d = rec["data"]
    out: List[Dict[str, Any]] = []
    for entry in d.get("in_lehmer_band", []) or []:
        m = entry.get("M_numpy")
        if m is None:
            continue
        try:
            m = float(m)
        except Exception:
            continue
        if not math.isfinite(m):
            continue
        out.append(
            {
                "arm": "lehmer_brute_force_smoke",
                "seed": None,
                "M": m,
                "coeffs": tuple(entry.get("coeffs_ascending", [])),
                "reward_label": "in_lehmer_band",
                "via": "exhaustive_search",
                "in_mossinghoff": entry.get("in_mossinghoff"),
            }
        )
    return out

def load_mossinghoff_catalog() -> List[Dict[str, Any]]:
    """Return the embedded Mossinghoff snapshot.

    Read-only; we don't modify the catalog module.  If import fails for
    any reason we degrade to an empty list.
    """
    try:
        from prometheus_math.databases.mahler import MAHLER_TABLE
        return list(MAHLER_TABLE)
    except Exception:
        return []

def _to_power_basis_coeffs(value) -> list[int]:
    """Convert a PARI eigenvalue (int or Mod(poly, defpoly)) to ascending
    power-basis coefficient list [c_0, c_1, ..., c_{r-1}].

    For dim=1 newforms, returns a single-element list [a_p]. For dim>1
    returns the coefficient vector matching LMFDB's `ap[i]` storage.
    """
    try:
        return [int(value)]
    except Exception:
        pass
    # PARI Mod: extract via lift -> Vecrev (ascending coefficients).
    try:
        lifted = pari.lift(value)
        coeffs = pari.Vecrev(lifted)
        return [int(c) for c in coeffs]
    except Exception as e:
        raise RuntimeError(
            f"could not coerce PARI value {value!r} to integer "
            f"power-basis coefficients: {e}"
        ) from e

def _to_eigenvalue(value, prec: str = "exact"):
    """Format a PARI eigenvalue for return.

    prec='exact' returns int for dim=1, otherwise the PARI Mod string.
    prec='complex' returns a complex number (numerical embedding).
    prec='coeffs' returns the ascending power-basis coeff list.
    """
    if prec == "coeffs":
        return _to_power_basis_coeffs(value)
    coeffs = _to_power_basis_coeffs(value)
    if prec == "exact":
        if len(coeffs) == 1:
            return coeffs[0]
        # Higher-dim: return PARI's Mod string repr (researcher-readable).
        return str(value)
    if prec == "complex":
        if len(coeffs) == 1:
            return complex(coeffs[0])
        # Numerically embed the Hecke field's first real root into C.
        try:
            num = pari.subst(pari.lift(value), "y", pari.polroots(pari.minpoly(value))[0])
            return complex(float(pari.real(num)), float(pari.imag(num)))
        except Exception:
            return complex("nan")
    raise ValueError(
        f"unknown prec {prec!r}; expected 'exact' / 'complex' / 'coeffs'"
    )

def bulk_eigenvalues(
    labels: Iterable[str], p_max: int = 100, prec: str = "exact"
) -> dict[str, dict[int, Union[int, str, list[int]]]]:
    """Compute eigenvalue tables for many newforms.

    Levels/weights are deduplicated so PARI mfinit is called once per
    (level, weight) space rather than once per label. This is a 5-50x
    speedup when sweeping many labels in the same space.

    Returns {label: {p: a_p, ...}, ...}.
    """
    if not isinstance(p_max, int) or p_max < 2:
        raise ValueError(f"p_max must be int >= 2, got {p_max!r}")
    primes_list = list(sieve.primerange(2, p_max + 1))
    out: dict[str, dict[int, Union[int, str, list[int]]]] = {}
    # Group labels by (level, weight) to leverage the eigenform cache.
    groups: dict[tuple[int, int], list[tuple[str, str]]] = {}
    for lbl in labels:
        level, weight, _, letter = _parse_label(lbl)
        groups.setdefault((level, weight), []).append((lbl, letter))
    for (level, weight), group in groups.items():
        for lbl, letter in group:
            f = _select_form(level, weight, letter)
            tbl: dict[int, Union[int, str, list[int]]] = {}
            for p in primes_list:
                ap = safe_call(pari.mfcoef, f, p)
                tbl[p] = _to_eigenvalue(ap, prec=prec)
            out[lbl] = tbl
    return out

def aggregate_by_operator(
    vectors: List[KillVector],
) -> Dict[str, Dict[str, float]]:
    """Compute ``E[k_i | operator]`` over a corpus of KillVectors.

    Returns a nested dict::

        {
            operator_class: {
                falsifier_name: P(triggered=True | operator),
                ...,
                f"{falsifier_name}__mean_squashed": E[squashed_margin],
                f"__count": N,
            },
            ...
        }

    This is the directional-derivative input the Day-4 learner consumes.
    Implementation is intentionally simple (one pass, dict math) so it
    can run inside the kernel's read-path without dragging numpy in.
    """
    by_op: Dict[str, Dict[str, List[float]]] = {}
    counts: Dict[str, int] = {}

    for v in vectors:
        op = v.operator_class or "_unknown"
        bucket = by_op.setdefault(op, {})
        counts[op] = counts.get(op, 0) + 1
        for c in v.components:
            tk = bucket.setdefault(c.falsifier_name, [])
            tk.append(1.0 if c.triggered else 0.0)
            sk = bucket.setdefault(f"{c.falsifier_name}__squashed", [])
            sk.append(c.squashed())

    out: Dict[str, Dict[str, float]] = {}
    for op, bucket in by_op.items():
        d: Dict[str, float] = {"__count": float(counts.get(op, 0))}
        for k, vs in bucket.items():
            if vs:
                d[k] = sum(vs) / len(vs)
        out[op] = d
    return out

def to_legacy_kill_path(self) -> Optional[str]:
    """Render the kill_vector to the legacy ``kill_path: str``
    format used by older pipeline records.  Returns None if no
    component triggered (i.e. the candidate would PROMOTE)."""
    c = self.first_triggered
    if c is None:
        return None
    # Reproduce the kill_pattern strings from discovery_pipeline._
    # process_candidate's Phase 2 ladder.
    name = c.falsifier_name
    meta = c.metadata or {}
    if name == "out_of_band":
        m = meta.get("M") or meta.get("mahler_measure") or "?"
        return f"out_of_band:M={m}_outside_(1.001,1.18)"
    if name == "reciprocity":
        return "reciprocity_failed"
    if name == "irreducibility":
        rat = str(meta.get("rationale", "reducible"))[:80]
        return f"reducible:{rat}"
    if name.startswith("catalog:"):
        cat = name.split(":", 1)[1]
        label = meta.get("match_label", "?")
        return f"known_in_catalog:matches {cat} entry {label}"
    if name == "F1_permutation_null":
        rat = str(meta.get("rationale", ""))[:80]
        return f"F1_kill:{rat}"
    if name == "F6_base_rate":
        rat = str(meta.get("rationale", ""))[:80]
        return f"F6_kill:{rat}"
    if name == "F9_simpler_explanation":
        rat = str(meta.get("rationale", ""))[:80]
        return f"F9_kill:{rat}"
    if name == "F11_cross_validation":
        rat = str(meta.get("rationale", ""))[:80]
        return f"F11_kill:{rat}"
    return f"{name}_kill"

def from_dict(cls, d: Dict[str, Any]) -> "KillVector":
    comps = tuple(
        KillComponent.from_dict(c) for c in (d.get("components") or [])
    )
    return cls(
        components=comps,
        candidate_hash=str(d.get("candidate_hash", "")),
        operator_class=str(d.get("operator_class", "")),
        region_meta=dict(d.get("region_meta") or {}),
        timestamp=float(d.get("timestamp", 0.0) or 0.0),
    )

def compute_mahler_batch_descending(coeff_matrix: np.ndarray) -> np.ndarray:
    """Compute Mahler measure for a batch of polynomials in descending form.

    Thin wrapper around ``techne.lib.mahler_measure.mahler_measure_padded``
    that operates on a (n_polys, deg+1) matrix in descending order.

    Returns ndarray of float64 of length n_polys.
    """
    from techne.lib.mahler_measure import mahler_measure_padded

    if coeff_matrix.ndim != 2:
        raise ValueError(
            f"coeff_matrix must be 2-D; got shape {coeff_matrix.shape}"
        )
    return mahler_measure_padded(coeff_matrix.astype(np.complex128))

def filter_band_candidates(
    half_coeffs_batch: list[tuple[int, ...]],
    M_values: np.ndarray,
    band_lower: float = 1.0 + 1e-6,
    band_upper: float = DEFAULT_BAND_UPPER,
) -> list[tuple[tuple[int, ...], float]]:
    """Return (half_coeffs, M) pairs strictly inside (band_lower, band_upper).

    The lower bound excludes M = 1 cyclotomic-like polys at numerical
    precision; the upper bound is the +100 Lehmer band cap.
    """
    out: list[tuple[tuple[int, ...], float]] = []
    if len(half_coeffs_batch) != len(M_values):
        raise ValueError(
            f"length mismatch: {len(half_coeffs_batch)} half_coeffs vs "
            f"{len(M_values)} M values"
        )
    for hc, M in zip(half_coeffs_batch, M_values):
        if not np.isfinite(M):
            continue
        m = float(M)
        if band_lower < m < band_upper:
            out.append((hc, m))
    return out

def hecke_eigenvalue(label: str, p: int):
    """Return the Hecke eigenvalue ``a_p`` at prime ``p``.

    Equivalent to ``q_coefficient(label, p)`` for an eigenform; the
    separate name documents the caller's intent and validates that
    ``p`` is prime.
    """
    if not isinstance(p, int) or p < 2:
        raise ValueError(f"p must be a prime integer >= 2; got {p!r}")
    if not _is_prime(p):
        raise ValueError(f"p must be prime; got {p}")
    return q_coefficient(label, p)

def coverage_stats(episodes: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    """Coverage: per-component, what fraction of episodes have non-None margin?"""
    n_total = len(episodes)
    if n_total == 0:
        return {"n_total": 0, "per_component": {}}

    triggered_count: Counter = Counter()
    margin_count: Counter = Counter()
    component_seen: Counter = Counter()
    has_any_margin = 0

    for e in episodes:
        kv = e["kill_vector"]
        any_margin = False
        for c in kv["components"]:
            name = c["falsifier_name"]
            component_seen[name] += 1
            if c["triggered"]:
                triggered_count[name] += 1
            if c["margin"] is not None:
                margin_count[name] += 1
                any_margin = True
        if any_margin:
            has_any_margin += 1

    per_component = {}
    for name in PILOT_COMPONENTS:
        seen = component_seen.get(name, 0)
        per_component[name] = {
            "n_seen": seen,
            "n_triggered": triggered_count.get(name, 0),
            "n_with_margin": margin_count.get(name, 0),
            "triggered_rate": (
                triggered_count.get(name, 0) / seen if seen > 0 else 0.0
            ),
            "margin_coverage": (
                margin_count.get(name, 0) / seen if seen > 0 else 0.0
            ),
        }
    return {
        "n_total": n_total,
        "n_with_any_margin": has_any_margin,
        "fraction_with_any_margin": has_any_margin / max(n_total, 1),
        "per_component": per_component,
    }

def operator_chart_margin_space(
    episodes: Sequence[Dict[str, Any]],
) -> Dict[str, Dict[str, Any]]:
    """For each operator (algorithm), compute E[k | operator] using the
    FULL kill_vector (squashed margins as a [0, 1] kill-strength PER
    component), not just triggered/not."""
    by_op: Dict[str, Dict[str, List[float]]] = defaultdict(lambda: defaultdict(list))
    by_op_triggered: Dict[str, Dict[str, List[float]]] = defaultdict(lambda: defaultdict(list))

    for e in episodes:
        op = e["algorithm"]
        for c in e["kill_vector"]["components"]:
            name = c["falsifier_name"]
            # Squashed margin (the unit-aware kill-strength).
            kc = KillComponent.from_dict(c)
            sq = kc.squashed()
            by_op[op][name].append(float(sq))
            by_op_triggered[op][name].append(1.0 if c["triggered"] else 0.0)

    out: Dict[str, Dict[str, Any]] = {}
    for op, comps in by_op.items():
        e_k = {}
        e_trig = {}
        for name in PILOT_COMPONENTS:
            arr = comps.get(name, [])
            tarr = by_op_triggered[op].get(name, [])
            e_k[name] = float(np.mean(arr)) if arr else 0.0
            e_trig[name] = float(np.mean(tarr)) if tarr else 0.0
        out[op] = {
            "n_episodes": int(sum(len(v) for v in by_op_triggered[op].values()) //
                              max(len(by_op_triggered[op]), 1)),
            "E_k_squashed_per_component": e_k,
            "E_triggered_per_component": e_trig,
        }
    return out

def f6_margin_cluster_analysis(
    episodes: Sequence[Dict[str, Any]],
) -> Dict[str, Any]:
    """For candidates that legacy would have categorically lumped as
    'F6_base_rate killed', what's the distribution of their F6 margin
    z-scores?  Tight cluster = legacy was hiding fine structure.
    """
    margins: List[float] = []
    triggered_margins: List[float] = []
    untriggered_margins: List[float] = []
    for e in episodes:
        for c in e["kill_vector"]["components"]:
            if c["falsifier_name"] != "F6_base_rate":
                continue
            m = c["margin"]
            if m is None or not math.isfinite(m):
                continue
            margins.append(float(m))
            if c["triggered"]:
                triggered_margins.append(float(m))
            else:
                untriggered_margins.append(float(m))
    if not margins:
        return {
            "n": 0, "n_triggered": 0, "n_untriggered": 0,
            "mean": None, "std": None, "unique_values": [],
        }
    arr = np.asarray(margins, dtype=float)
    uniq, counts = np.unique(arr, return_counts=True)
    return {
        "n": int(arr.size),
        "n_triggered": int(len(triggered_margins)),
        "n_untriggered": int(len(untriggered_margins)),
        "mean": float(arr.mean()),
        "std": float(arr.std()),
        "median": float(np.median(arr)),
        "min": float(arr.min()),
        "max": float(arr.max()),
        "unique_values": [
            {"value": float(v), "count": int(c)} for v, c in zip(uniq, counts)
        ][:20],   # cap the histogram for JSON size
        "n_unique_values": int(uniq.size),
        "verdict": (
            "spread"
            if arr.std() > 0.5
            else "tight_cluster_or_bimodal"
        ),
    }

def gamma(z, prec: int = 53):
    """Gamma function Γ(z) at arbitrary precision (BITS)."""
    with workprec(prec):
        return mpmath.gamma(z)

def beta(a, b, prec: int = 53):
    """Beta function B(a, b) = Γ(a)Γ(b)/Γ(a+b) at arbitrary precision."""
    with workprec(prec):
        return mpmath.beta(a, b)

def run_densification(
    cells: Sequence[RegionCell] = DEFAULT_REGION_CELLS,
    n_episodes_per_cell: int = 1000,
    seeds: Tuple[int, ...] = (0, 1, 2),
    algorithms: Tuple[str, ...] = (
        "random_uniform", "reinforce_linear", "ppo_mlp", "ga_elitist_v2",
    ),
    *,
    progress: bool = True,
) -> Dict[str, Any]:
    """Run native KillVector pilots on multiple region cells.

    Returns a dict with the same shape as ``run_pilot`` from
    ``native_kill_vector_pilot`` so the navigator can consume both:

      * meta: setup
      * episodes: list[EpisodeKillVector.to_dict()]
      * cell_summary: {(cell_id, algo, seed): {n, n_pipeline_routed, ...}}
      * elapsed_s: total wall time
    """
    t_global = time.perf_counter()
    all_episodes: List[EpisodeKillVector] = []
    cell_summary: Dict[str, Dict[str, Any]] = {}
    skipped: List[str] = []

    for cell in cells:
        for algo in algorithms:
            if algo not in CELL_ALGORITHM_RUNNERS:
                raise ValueError(f"unknown algorithm {algo!r}")
            runner = CELL_ALGORITHM_RUNNERS[algo]
            for s in seeds:
                t0 = time.perf_counter()
                key = f"{cell.cell_id}|{algo}@seed={s}"
                if progress:
                    print(
                        f"[densify] {key} (target={n_episodes_per_cell} eps)...",
                        flush=True,
                    )
                try:
                    eps = runner(cell, n_episodes_per_cell, int(s))
                except Exception as e:
                    if progress:
                        print(
                            f"  ERROR in {key}: {type(e).__name__}: {e!r}",
                            flush=True,
                        )
                    skipped.append(f"{key}: {type(e).__name__}")
                    eps = []
                elapsed = time.perf_counter() - t0
                n_pipeline = sum(
                    1 for e in eps if e.pipeline_terminal_state is not None
                )
                cell_summary[key] = {
                    "cell_id": cell.cell_id,
                    "algorithm": algo,
                    "seed": int(s),
                    "n_episodes": len(eps),
                    "n_pipeline_routed": n_pipeline,
                    "elapsed_s": elapsed,
                    "skipped": len(eps) == 0 and n_episodes_per_cell > 0,
                }
                all_episodes.extend(eps)
                if progress:
                    print(
                        f"  -> {len(eps)} eps, {n_pipeline} pipeline-routed,"
                        f" {elapsed:.1f}s ({len(eps)/max(elapsed,1e-9):.1f} eps/s)",
                        flush=True,
                    )

    elapsed = time.perf_counter() - t_global
    return {
        "meta": {
            "n_episodes_per_cell": int(n_episodes_per_cell),
            "seeds": list(seeds),
            "algorithms": list(algorithms),
            "cells": [
                {
                    "cell_id": c.cell_id,
                    "degree": c.degree,
                    "alphabet_width": c.alphabet_width,
                    "alphabet_size": c.alphabet_size,
                    "reward_shape": c.reward_shape,
                }
                for c in cells
            ],
            "pilot_components": list(PILOT_COMPONENTS),
        },
        "episodes": [e.to_dict() for e in all_episodes],
        "cell_summary": cell_summary,
        "skipped": skipped,
        "elapsed_s": float(elapsed),
        "total_episodes": len(all_episodes),
    }

def _objective_minimize_mahler_measure(
    eval_result: Any,
    args: Tuple[Any, ...],
    arg_label: str,
) -> Tuple[float, bool]:
    """Reward for finding low-M reciprocal polys.

    Returns (reward, hit_target).

    Reward shape:
    - +1.0 for any M finite in [1, 5)
    - +5.0 if M < 2.0
    - +20.0 if M < 1.5 (Lehmer-territory)
    - +100.0 if M < 1.18 (sub-Lehmer; would be a real find)
    - 0.0 otherwise (NaN, M>=5, etc.)
    """
    try:
        m = float(eval_result)
    except (TypeError, ValueError):
        return 0.0, False
    if not math.isfinite(m):
        return 0.0, False
    if m < 1.0 - 1e-9:
        # Reciprocal poly with M < 1 should not exist; numerical artifact.
        return 0.0, False
    hit = m < 1.18
    if m < 1.18:
        return 100.0, True
    if m < 1.5:
        return 20.0, False
    if m < 2.0:
        return 5.0, False
    if m < 5.0:
        return 1.0, False
    return 0.0, False

def _track_best(
    info: Dict[str, Any], best_value: Optional[float]
) -> Optional[float]:
    """Track minimum-Mahler (or other) finite output across an episode."""
    v = info.get("output_value")
    try:
        v = float(v)
    except (TypeError, ValueError):
        return best_value
    if not math.isfinite(v) or v < 1.0 - 1e-9:
        return best_value
    if best_value is None or v < best_value:
        return v
    return best_value

def _as_numpy(tensor) -> np.ndarray:
    """Coerce input to a numpy.ndarray of dtype float64.

    Rejects bare scalars, lists-of-strings, etc.  Lists / tuples of
    numbers are accepted (per numpy's array constructor).
    """
    if tensor is None:
        raise ValueError("tensor input is None")
    if isinstance(tensor, (str, bytes)):
        raise ValueError("tensor input must be array-like, got string")
    try:
        arr = np.asarray(tensor, dtype=np.float64)
    except (TypeError, ValueError) as e:
        raise ValueError(f"cannot interpret input as a tensor: {e}")
    if arr.ndim == 0:
        raise ValueError("tensor must have ndim >= 1, got a scalar")
    if not np.all(np.isfinite(arr)):
        raise ValueError("tensor contains NaN or inf")
    return arr

def cp_reconstruct(
    factors: Sequence[np.ndarray],
    weights: Optional[np.ndarray] = None,
) -> np.ndarray:
    """Reconstruct a dense tensor from CP factors.

    T_{i_1...i_d} = Σ_r λ_r · ∏_k F^{(k)}_{i_k, r}
    """
    if not factors:
        raise ValueError("factors must be a non-empty sequence")
    factors = [np.asarray(f, dtype=np.float64) for f in factors]
    rank = factors[0].shape[1]
    for k, f in enumerate(factors):
        if f.ndim != 2:
            raise ValueError(f"factor {k} must be 2-D, got shape {f.shape}")
        if f.shape[1] != rank:
            raise ValueError(
                f"factor {k} has rank {f.shape[1]} but factor 0 has rank {rank}"
            )
    if weights is None:
        weights = np.ones(rank, dtype=np.float64)
    else:
        weights = np.asarray(weights, dtype=np.float64).reshape(-1)
        if weights.shape[0] != rank:
            raise ValueError(
                f"weights has length {weights.shape[0]} but rank is {rank}"
            )
    out = cp_to_tensor((weights, factors))
    return np.asarray(out, dtype=np.float64)

def tucker_reconstruct(
    core: np.ndarray,
    factors: Sequence[np.ndarray],
) -> np.ndarray:
    """Reconstruct dense tensor from Tucker decomposition."""
    core = np.asarray(core, dtype=np.float64)
    factors = [np.asarray(f, dtype=np.float64) for f in factors]
    if len(factors) != core.ndim:
        raise ValueError(
            f"factors has length {len(factors)} but core has ndim {core.ndim}"
        )
    out = _tucker_to_tensor((core, factors))
    return np.asarray(out, dtype=np.float64)

def tt_reconstruct(cores: Sequence[np.ndarray]) -> np.ndarray:
    """Reconstruct a dense tensor from TT cores."""
    if not cores:
        raise ValueError("cores must be a non-empty sequence")
    cores = [np.asarray(c, dtype=np.float64) for c in cores]
    for k, c in enumerate(cores):
        if c.ndim != 3:
            raise ValueError(f"core {k} must be 3-D, got shape {c.shape}")
    if cores[0].shape[0] != 1:
        raise ValueError(
            f"first core must have leading bond dim 1, got {cores[0].shape[0]}"
        )
    if cores[-1].shape[2] != 1:
        raise ValueError(
            f"last core must have trailing bond dim 1, got {cores[-1].shape[2]}"
        )
    for k in range(len(cores) - 1):
        if cores[k].shape[2] != cores[k + 1].shape[0]:
            raise ValueError(
                f"bond mismatch between core {k} (right={cores[k].shape[2]}) "
                f"and core {k+1} (left={cores[k+1].shape[0]})"
            )
    out = _tt_to_tensor(cores)
    return np.asarray(out, dtype=np.float64)

def decomp_storage(decomp_dict: dict, kind: str) -> int:
    """Number of floats stored in a decomposition (compression measure).

    Parameters
    ----------
    decomp_dict : dict
        Output of cp_decompose / tucker_decompose / tt_decompose.
    kind : {"cp", "tucker", "tt"}
    """
    kind = kind.lower()
    if kind == "cp":
        n = sum(int(np.asarray(f).size) for f in decomp_dict["factors"])
        n += int(np.asarray(decomp_dict["weights"]).size)
        return n
    if kind == "tucker":
        n = int(np.asarray(decomp_dict["core"]).size)
        n += sum(int(np.asarray(f).size) for f in decomp_dict["factors"])
        return n
    if kind == "tt":
        return sum(int(np.asarray(c).size) for c in decomp_dict["cores"])
    raise ValueError(f"kind must be 'cp', 'tucker', or 'tt', got {kind!r}")

