def _trigger_flags_per_component(
    vectors: Sequence[KillVector],
    component_names: Sequence[str],
) -> Dict[str, List[int]]:
    """Build {component_name -> list of 0/1 trigger flags across corpus}."""
    n = len(vectors)
    flags: Dict[str, List[int]] = {name: [0] * n for name in component_names}
    for i, kv in enumerate(vectors):
        triggered_set = {c.falsifier_name for c in kv.components if c.triggered}
        for name in component_names:
            if name in triggered_set:
                flags[name][i] = 1
    return flags

def corpus_summary(corpus: Iterable[BSDEntry]) -> dict[str, Any]:
    """Diagnostic counts: total + per-rank tallies."""
    corpus = list(corpus)
    counts: dict[int, int] = {}
    for e in corpus:
        counts[e.rank] = counts.get(e.rank, 0) + 1
    return {
        "n_total": len(corpus),
        "rank_counts": dict(sorted(counts.items())),
        "max_rank": max((e.rank for e in corpus), default=None),
    }

def _iso_class_from_label(label: str) -> str:
    """Extract "N.x" prefix (the isogeny-class portion) from a g2c label."""
    parts = label.split(".")
    if len(parts) >= 2:
        return f"{parts[0]}.{parts[1]}"
    return label

def corpus_summary(corpus: Iterable[Genus2Entry]) -> dict:
    """Diagnostic counts: total + per-rank-class + conductor stats."""
    corpus = list(corpus)
    by_class: dict[int, int] = {0: 0, 1: 0, 2: 0}
    for e in corpus:
        by_class[e.rank_class] = by_class.get(e.rank_class, 0) + 1
    conductors = [e.conductor for e in corpus]
    return {
        "n_total": len(corpus),
        "rank_class_counts": dict(sorted(by_class.items())),
        "cond_min": min(conductors) if conductors else None,
        "cond_max": max(conductors) if conductors else None,
        "cond_mean": (sum(conductors) / len(conductors)) if conductors else None,
    }

def _mossinghoff_check_factor(non_cyclo_factors, M_non_cyclo_product):
    """Cross-check the non-cyclotomic factor product against Mossinghoff.

    1. Coefficient match (with x -> -x flip) of the product.
    2. M-value proximity match (tol 1e-6).

    Returns dict {in_catalog, label, match_method}.
    """
    if not non_cyclo_factors:
        return {"in_catalog": None, "label": None, "match_method": "no_non_cyclotomic_factor"}
    try:
        from prometheus_math.databases.mahler import lookup_polynomial, lookup_by_M
    except Exception as exc:  # pragma: no cover
        return {"in_catalog": None, "label": None, "match_method": f"db_import_error: {exc}"}

    # Build product
    prod = sp.Poly(1, _x, domain="ZZ")
    for fp, mult in non_cyclo_factors:
        prod = prod * (fp ** mult)
    coeffs_desc = [int(c) for c in prod.all_coeffs()]
    coeffs_asc = list(reversed(coeffs_desc))

    # Coefficient match (and x -> -x flipped)
    entry = lookup_polynomial(coeffs_asc)
    if entry is not None:
        return {
            "in_catalog": True,
            "label": str(entry.get("name", "Mossinghoff (unnamed)")),
            "match_method": "coefficient_exact",
        }
    flipped = [c if i % 2 == 0 else -c for i, c in enumerate(coeffs_asc)]
    entry = lookup_polynomial(flipped)
    if entry is not None:
        return {
            "in_catalog": True,
            "label": str(entry.get("name", "Mossinghoff (unnamed)")),
            "match_method": "coefficient_xflip",
        }

    # M-value match
    if M_non_cyclo_product is not None and math.isfinite(M_non_cyclo_product):
        M_hits = lookup_by_M(float(M_non_cyclo_product), tol=1e-6)
        if M_hits:
            # Prefer same-degree match
            deg = sum(fp.degree() * mult for fp, mult in non_cyclo_factors)
            same_deg = [h for h in M_hits if h.get("degree") == deg]
            chosen = same_deg[0] if same_deg else M_hits[0]
            return {
                "in_catalog": True,
                "label": str(chosen.get("name", "Mossinghoff (M-match)")),
                "match_method": (
                    f"M_value_match (tol=1e-6, "
                    f"{'same_degree' if same_deg else 'any_degree'})"
                ),
            }

    return {
        "in_catalog": False,
        "label": None,
        "match_method": "no_match",
    }

def _hash_candidate(*parts: Any) -> str:
    """SHA-256 hex digest over the string-rendered ``parts``. Used to
    bind a KillVector to the specific (env, episode-key) being scored
    so the Learner can dedupe across runs."""
    h = hashlib.sha256()
    for p in parts:
        h.update(str(p).encode("utf-8"))
        h.update(b"\x00")
    return h.hexdigest()

