def test_cartan_matrix_offdiagonal_nonpositive_integers(type_, rank):
    """Off-diagonal Cartan entries are non-positive integers in {0,-1,-2,-3}.

    Reference: Humphreys 9.4, axiom (C2).
    """
    C = cartan_matrix(type_, rank)
    for i in range(rank):
        for j in range(rank):
            if i == j:
                continue
            assert C[i, j] in (0, -1, -2, -3), (
                f"{type_}_{rank} C[{i},{j}] = {C[i,j]} out of range"
            )

def test_all_roots_is_double_positive(type_, rank):
    """all_roots = positive_roots ∪ -positive_roots, |all| = 2 * |pos|."""
    pos = positive_roots(type_, rank)
    allr = all_roots(type_, rank)
    assert len(allr) == 2 * len(pos)
    # Each negative root is the negation of some positive one.
    pos_set = {tuple(p.tolist()) for p in pos}
    neg_set = {tuple((-p).tolist()) for p in pos}
    expected = pos_set | neg_set
    actual = {tuple(r.tolist()) for r in allr}
    assert actual == expected

def test_weyl_generators_are_involutions(type_, rank):
    """Each simple reflection s_i satisfies s_i^2 = I."""
    gens = weyl_group_generators(type_, rank)
    for s in gens:
        prod = s @ s
        assert np.allclose(prod, np.eye(prod.shape[0]), atol=1e-9)

def _det_int(M):
    """Integer determinant via numpy float, rounded."""
    return int(round(float(np.linalg.det(np.array(M, dtype=float)))))

def test_composition_bruhat_distance_equals_length_diff():
    """When w <= v, bruhat_distance(w, v) = l(v) - l(w).

    Composition test: bruhat_distance + num_inversions consistency
    via Bruhat order being graded with rank = length.
    Reference: Bjorner-Brenti (2005), Theorem 2.2.6.
    """
    for w in _all_perms(3):
        for v in _all_perms(3):
            d = bruhat_distance(w, v)
            if bruhat_le(w, v):
                assert d == num_inversions(v) - num_inversions(w)
            elif bruhat_le(v, w):
                assert d == num_inversions(w) - num_inversions(v)
            else:
                assert d is None

def capture(cls, kv: KillVector) -> "_ReplayCapsule":
    d = kv.to_dict()
    # Strip non-content timestamp so capsule comparison is
    # content-addressed (timestamp is wall-clock at construction;
    # would otherwise spuriously vary across capture/replay calls).
    # Per ReplayCapsule proposal §"Bit-identity check": SHA256 of
    # the canonicalized output JSON, where canonicalization removes
    # incidental fields.
    d_for_hash = {k: v for k, v in d.items() if k != "timestamp"}
    canonical = json.dumps(
        d_for_hash, sort_keys=True, separators=(",", ":"), default=str
    )
    sha = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
    return cls(
        captured_dict=d,
        captured_canonical_json=canonical,
        captured_sha256=sha,
    )

def replay(self) -> KillVector:
    """Reconstruct the KillVector from the captured dict."""
    return KillVector.from_dict(self.captured_dict)

