def _evaluate_relation(a_val: int, b_val: int, relation: str) -> bool:
    if relation == "equal":
        return a_val == b_val
    if relation == "equal_mod_2":
        return (a_val % 2) == (b_val % 2)
    if relation == "divides":
        # divides(a, b) = "does a divide b?". Mathematically:
        # - Every nonzero a divides 0 (since 0 = 0*a). FIRE #22 FIX:
        #   previously this returned False for b_val=0, biasing rank=0
        #   records (common in our BSD-rich catalog) toward REJECTED.
        # - 0 divides nothing (except 0 itself by convention here:
        #   divides(0, 0) → True since 0 == 0*anything is vacuously OK).
        if a_val == 0:
            return b_val == 0
        return (b_val % a_val) == 0
    if relation.startswith("abs_diff_le_"):
        # Parse K from "abs_diff_le_K" (any non-negative integer).
        # Bug fix (Fire #3): previously only the literal "abs_diff_le_3"
        # was handled; mutated K values (from C2/C4/D2) silently
        # evaluated to False, producing spurious kills.
        try:
            k = int(relation.split("_")[-1])
            return abs(a_val - b_val) <= k
        except ValueError:
            return False
    return False

def _knot_mirror_op(obj: Dict[str, Any]) -> Dict[str, Optional[int]]:
    """Mirror reflection: negates signature, preserves others."""
    sig = _get_int(obj, "signature")
    return {
        "crossing_number": _get_int(obj, "crossing_number"),
        "signature": -sig if sig is not None else None,
        "determinant": _get_int(obj, "determinant"),
        "three_genus": _get_int(obj, "three_genus"),
    }

def _ec_quadratic_twist_op_modeled(obj: Dict[str, Any]) -> Dict[str, Optional[int]]:
    """Quadratic twist (modeled): preserves conductor's radical structure
    but can flip parity of rank. v0.1 model: rank stays, conductor stays,
    tamagawa product may change. Real implementation in Tier 1."""
    return {
        "rank": _get_int(obj, "rank"),
        "conductor": _get_int(obj, "conductor"),
        "tamagawa_product": _get_int(obj, "tamagawa_product"),
        "torsion": _get_int(obj, "torsion"),
    }

def description(self) -> str:
    n_pairs = sum(
        len(idxs) * (len(idxs) - 1) // 2 for _, idxs in self._groups
    )
    return (
        f"g1: Galois twist invariance (EC×EC sharing exact j-invariant); "
        f"{len(self._groups)} twist-classes spanning {n_pairs} pairs "
        f"× {len(EC_INTEGER_INVARIANTS)} invariants"
    )

def _get_rank(ec: Dict[str, Any]) -> Optional[int]:
    base = ec.get("base", {})
    r = base.get("rank")
    if r is None:
        return None
    try:
        return int(r)
    except (TypeError, ValueError):
        return None

