def mahler_measure_from_roots(coeffs: list[int]) -> float:
    """
    Compute Mahler measure via roots.
    M(P) = |a_n| * prod max(1, |root_i|)

    coeffs: [a0, a1, ..., a_n] where a0 is constant term, a_n is leading.
    numpy wants [a_n, ..., a1, a0] for np.roots.
    """
    if len(coeffs) < 2:
        return float('nan')

    leading = abs(coeffs[-1])
    if leading == 0:
        return float('nan')

    # np.roots wants highest degree first
    poly_np = list(reversed(coeffs))

    try:
        roots = np.roots(poly_np)
    except Exception:
        return float('nan')

    absroots = np.abs(roots)
    product = np.prod(np.maximum(1.0, absroots))
    return leading * product

def compute_rank_profiles(data):
    """Stratify by rank instead of class_size, as a sanity check."""
    # Flatten all curves
    all_curves = []
    for cs, curves in data.items():
        for c in curves:
            c['class_size'] = cs
            all_curves.append(c)

    rank_groups = defaultdict(list)
    for c in all_curves:
        if c['rank'] >= 0:
            rank_groups[c['rank']].append(c)

    sqrt_p = {p: np.sqrt(p) for p in PRIMES}
    profiles = {}

    for rank, curves in sorted(rank_groups.items()):
        if len(curves) < 50:
            continue
        print(f"\nRank={rank}: {len(curves)} curves")
        # Reuse already-computed a_p? No, we need to recompute grouped differently.
