def confidence(self, prompt: str, answer: str) -> float:
    # Generate a synthetic candidate list to rank the specific answer against
    # We simulate a "wrong" alternative to gauge relative confidence
    if answer.strip().lower() in ["yes", "no", "true", "false"]:
        other = "No" if answer.strip().lower() in ["yes", "true"] else "Yes"
    else:
        other = "I don't know"

    candidates = [answer, other]
    ranked = self.evaluate(prompt, candidates)

    if not ranked:
        return 0.0

    top = ranked[0]
    if top["candidate"] == answer:
        # Normalize score to 0-1 range roughly based on typical output spread
        conf = min(1.0, max(0.0, (top["score"] + 1.0) / 2.0))
        return conf
    else:
        # If the provided answer isn't the top one, confidence is low
        # But check if it's close
        scores = [r["score"] for r in ranked if r["candidate"] == answer]
        if scores:
            return max(0.0, min(0.4, (scores[0] + 1.0) / 2.0))
        return 0.0

def __init__(self):
    self.basis_size = 64  # Number of spectral modes
    self.temperatures = np.linspace(0.1, 1.0, self.basis_size) # Adaptive temps

def _hash_to_spectrum(self, text: str) -> np.ndarray:
    """Convert text to a spectral representation using character frequencies as amplitudes."""
    if not text:
        return np.zeros(self.basis_size)

    # Simple char-to-float mapping
    chars = [ord(c) / 256.0 for c in text]
    spectrum = np.zeros(self.basis_size)

    # Construct superposition of basis functions
    for i, val in enumerate(chars):
        freq = (i % (self.basis_size // 2)) + 1
        phase = val * 2 * np.pi
        # Superposition: Amplitude modulated by char value, frequency by position
        spectrum[freq-1] += np.sin(phase) * val
        if freq < self.basis_size:
            spectrum[freq] += np.cos(phase) * val

    # Normalize
    norm = np.linalg.norm(spectrum)
    return spectrum / (norm + 1e-9)

def _compute_spectral_entropy_proxy(self, text: str) -> float:
    """
    Computes a proxy for spectral entropy based on character frequency distribution.
    Low entropy = ordered/repetitive (Low Energy state)
    High entropy = disordered/random (High Energy state)
    We want 'favorable' hypotheses to be parsimonious (low energy) but expressive.
    Here, we treat high entropy as a penalty term in the free energy equation.
    """
    if not text:
        return 0.0

    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1

    length = len(text)
    entropy = 0.0
    for count in counts.values():
        if count > 0:
            p = count / length
            entropy -= p * math.log2(p)

    return entropy

