    pl = prompt.lower()
    if re.search(r'^(is|are|was|were|do|does|did|can|could|should)\b', pl):
        return 'yes_no'
    if re.search(r'^(what|which|who|where|when|how|why)\b', pl):
        return 'wh_question'
    if any(w in pl for w in ['compare','rank','sort','order']):
        return 'ordering'
    return 'statement'

def _spectral_sim(self, prompt: str, cand: str) -> float:
    """Character-frequency spectral similarity."""
    def _spectrum(s):
        v = np.zeros(26)
        for c in s.lower():
            if 'a' <= c <= 'z':
                v[ord(c) - ord('a')] += 1
        n = np.linalg.norm(v)
        return v / n if n > 0 else v
    sp, sc = _spectrum(prompt), _spectrum(cand)
    return float((np.dot(sp, sc) + 1.0) / 2.0)

