def __init__(self):
    # Structural parsers acting as 'spectral filters'
    self.negation_words = {'no', 'not', 'never', 'none', 'neither', 'nobody', 'nothing'}
    self.comparative_ops = {'>', '<', '>=', '<=', 'greater', 'less', 'more', 'fewer', 'before', 'after'}
