def evaluate(self, prompt, candidates):
    """Rank candidates using ECC + mechanism design + property-based testing."""
    props = self._extract_propositions(prompt)

    # Build constraint satisfaction problem from propositions
    variables = list(range(len(props)))
    domains = {i: [0, 1] for i in variables}
    constraints = []

    # Add constraints from logical structure
    for i, prop in enumerate(props):
        if prop[0] == 'numeric':
            # Numeric comparison is deterministic
            constraints.append(lambda assignment, i=i, val=prop[2]: 
                             assignment.get(i, val) == val)
        elif prop[0] == 'conditional':
            # If premise then conclusion
            for j, other in enumerate(props):
                if i != j and prop[1].lower() in str(other).lower():
                    constraints.append(lambda assignment, i=i, j=j: 
                                     not assignment.get(i, 0) or assignment.get(j, 0))

    # Property-based testing: random assignments + shrinking
    valid_assignments = []
    for _ in range(self.n_tests):
        assignment = {i: np.random.randint(2) for i in variables}
        if all(c(assignment) for c in constraints):
            valid_assignments.append(assignment)

    # Reference codeword from valid assignments (majority vote)
    if valid_assignments:
        ref_bits = [int(np.mean([a.get(i, 0) for a in valid_assignments]) > 0.5) 
                   for i in variables]
    else:
        ref_bits = [1] * len(props) if props else [1]

    ref_code = self._hamming_encode(ref_bits)

    # Score each candidate
    scores = []
    prop_keys = [p[1] if len(p) > 1 else str(p) for p in props]

    for cand in candidates:
        # Structural score: proposition alignment
        cand_vec = self._proposition_vector(cand, prop_keys)
        if len(cand_vec) < len(ref_bits):
            cand_vec += [0] * (len(ref_bits) - len(cand_vec))
        cand_code = self._hamming_encode(cand_vec[:len(ref_bits)])

        # Hamming distance (proper scoring rule)
        dist = sum(a != b for a, b in zip(cand_code, ref_code[:len(cand_code)]))
        norm_dist = dist / max(len(cand_code), 1)
        struct_score = 1 - norm_dist

        # Constraint satisfaction score
        cand_assignment = {i: cand_vec[i] if i < len(cand_vec) else 0 
                         for i in variables}
        constraint_score = sum(c(cand_assignment) for c in constraints) / max(len(constraints), 1)

        # NCD tiebreaker (max 10%)
        ncd_score = 1 - self._ncd(prompt, cand)

        # Combine: 60% structural, 30% constraints, 10% NCD
        final_score = 0.6 * struct_score + 0.3 * constraint_score + 0.1 * ncd_score

        scores.append({
            'candidate': cand,
            'score': final_score,
            'reasoning': f"Hamming dist={norm_dist:.2f}, constraints={constraint_score:.2f}"
        })

    return sorted(scores, key=lambda x: x['score'], reverse=True)

def _extract_graph(self, text: str) -> Tuple[List[str], np.ndarray]:
    """Parse text into nodes and an adjacency tensor (n_nodes, n_nodes, n_rel_types)."""
    tokens = self._tokenize(text)
    words = [t for t in tokens if t.isalpha()]
    if not words:
        return [], np.array([])

    # Simplified node extraction: unique words as potential propositions
    # In a full system, this would be SVO triples. Here we simulate via keyword matching.
    nodes = list(set(words))
    n = len(nodes)
    if n == 0: return [], np.array([])

    # Adjacency: [i, j, r] = 1 means relation r exists from i to j
    adj = np.zeros((n, n, self.N_REL), dtype=float)

    text_lower = text.lower()

    # Helper to find indices
    def idx(w): 
        try: return nodes.index(w) 
        except ValueError: return -1

    # 1. Negations
    neg_patterns = [r'not\s+(\w+)', r'no\s+(\w+)', r'never\s+(\w+)']
    for pat in neg_patterns:
        for m in re.finditer(pat, text_lower):
            target = m.group(1)
            t_idx = idx(target)
            if t_idx != -1:
                # Self-loop or implicit subject negation
                adj[t_idx, t_idx, 0] = 1.0 

    # 2. Comparatives (<, >)
    comp_patterns = [
        (r'less\s+than\s+(\w+)', 1), (r'smaller\s+than\s+(\w+)', 1),
        (r'greater\s+than\s+(\w+)', 2), (r'larger\s+than\s+(\w+)', 2),
        (r'more\s+than\s+(\w+)', 2)
    ]
    # Simple heuristic: look for "A is less than B" structure is hard with regex alone.
    # Instead, detect presence of comparative keywords and link to nearest nouns.
    if 'less' in text_lower or 'smaller' in text_lower:
         # Mock logic: if multiple nodes, assume ordered
         if n >= 2: adj[0, 1, 1] = 1.0
    if 'greater' in text_lower or 'larger' in text_lower or 'more' in text_lower:
         if n >= 2: adj[1, 0, 2] = 1.0

    # 3. Conditionals & Causals
    if 'if' in text_lower or 'then' in text_lower:
        if n >= 2: adj[0, 1, 3] = 1.0 # implies
    if 'because' in text_lower or 'causes' in text_lower or 'leads to' in text_lower:
        if n >= 2: adj[0, 1, 4] = 1.0 # cause

    # 4. Equality
    if 'equal' in text_lower or 'same' in text_lower:
        if n >= 2: adj[0, 1, 5] = 1.0

    return nodes, adj

def _compute_criticality(self, M: np.ndarray) -> float:
    """Compute spectral radius and criticality score."""
    if M.shape[0] == 0: return 0.0
    try:
        eigenvals = np.linalg.eigvals(M.astype(float))
        rho = np.max(np.abs(eigenvals))
        # Criticality: 1 - |rho - 1|
        return 1.0 - abs(rho - 1.0)
    except:
        return 0.0

