    """
    signal = self._compute_evidence_stream(prompt, answer)
    spec_score = self._spectral_justification(signal)

    # Apply a strict penalty if the answer is too short to contain reasoning
    if len(answer.split()) < 3:
        spec_score *= 0.8

    return max(0.0, min(1.0, spec_score))

def _spectral_similarity(self, s1: np.ndarray, s2: np.ndarray) -> float:
    """Compute spectral similarity"""
    norm1 = np.linalg.norm(s1)
    norm2 = np.linalg.norm(s2)
    if norm1 + norm2 == 0:
        return 0.5
    diff = np.linalg.norm(s1 - s2)
    return 1.0 - (diff / (norm1 + norm2))

def _fourier_embed(self, features: np.ndarray) -> np.ndarray:
    """Compute magnitude of RFFT as spectral representation."""
    if len(features) == 0:
        return np.array([])
    spectrum = np.fft.rfft(features)
    return np.abs(spectrum)

