def _compute_psd(self, M: np.ndarray) -> np.ndarray:
    """Compute Power Spectral Density for each column (proposition signal)."""
    if M.shape[0] == 0:
        return np.zeros((0, 1))

    # FFT along axis 0 (time/token position)
    fft_res = np.fft.fft(M, axis=0)
    psd = np.abs(fft_res) ** 2
    return psd

def _graph_to_state_vector(self, G):
    """Convert graph to quantum-like state vector encoding relation types."""
    if len(G.nodes()) == 0:
        return np.zeros(len(self.relation_types))

    # Count relation types
    relation_counts = defaultdict(int)
    for _, _, data in G.edges(data=True):
        rel = data.get('relation', 'unknown')
        if rel in self.relation_types:
            relation_counts[rel] += 1

    # Build vector
    vec = np.array([relation_counts[r] for r in self.relation_types], dtype=float)
    norm = np.linalg.norm(vec)
    return vec / norm if norm > 0 else vec

