def _trigger_flags_per_component(
    vectors: Sequence[KillVector],
    component_names: Sequence[str],
) -> Dict[str, List[int]]:
    """Build {component_name -> list of 0/1 trigger flags across corpus}."""
    n = len(vectors)
    flags: Dict[str, List[int]] = {name: [0] * n for name in component_names}
    for i, kv in enumerate(vectors):
        triggered_set = {c.falsifier_name for c in kv.components if c.triggered}
        for name in component_names:
            if name in triggered_set:
                flags[name][i] = 1
    return flags

def corpus_summary(corpus: Iterable[BSDEntry]) -> dict[str, Any]:
    """Diagnostic counts: total + per-rank tallies."""
    corpus = list(corpus)
    counts: dict[int, int] = {}
    for e in corpus:
        counts[e.rank] = counts.get(e.rank, 0) + 1
    return {
        "n_total": len(corpus),
        "rank_counts": dict(sorted(counts.items())),
        "max_rank": max((e.rank for e in corpus), default=None),
    }

