def filter(crossing_number: Any = None,
           genus: Any = None,
           alternating: Any = None,
           determinant: Any = None,
           hyperbolic: Any = None,
           signature: Any = None,
           fibered: Any = None,
           l_space: Any = None) -> list[dict]:
    """Filter knots by computed invariants.

    Each parameter is either:
      * None         - don't filter on this attribute
      * a value      - exact match
      * a (lo, hi) tuple - inclusive range (numeric attributes only)

    Boolean filters (alternating, hyperbolic, fibered, l_space) accept
    True/False, and treat None values in the data as a non-match.
    """
    _ensure_loaded()
    knots: list[dict] = list(_cache["knots_list"] or [])

    def _match_numeric(val, spec) -> bool:
        if val is None:
            return False
        if isinstance(spec, tuple) and len(spec) == 2:
            lo, hi = spec
            try:
                return (lo is None or val >= lo) and (hi is None or val <= hi)
            except TypeError:
                return False
        return val == spec

    def _match_bool(val, spec) -> bool:
        if val is None:
            return False
        return bool(val) == bool(spec)

    out = []
    for k in knots:
        if crossing_number is not None and not _match_numeric(
                k.get("crossing_number"), crossing_number):
            continue
        if genus is not None and not _match_numeric(
                k.get("three_genus"), genus):
            continue
        if determinant is not None and not _match_numeric(
                k.get("determinant"), determinant):
            continue
        if signature is not None and not _match_numeric(
                k.get("signature"), signature):
            continue
        if alternating is not None and not _match_bool(
                k.get("alternating"), alternating):
            continue
        if fibered is not None and not _match_bool(
                k.get("fibered"), fibered):
            continue
        if hyperbolic is not None and not _match_bool(
                k.get("hyperbolic"), hyperbolic):
            continue
        if l_space is not None and not _match_bool(
                k.get("l_space"), l_space):
            continue
        out.append(k)
    return out

def _atkin_lehner_to_dict(eigenvals: Optional[list]) -> dict[int, int]:
    """Convert LMFDB ``atkin_lehner_eigenvals`` list-of-pairs to a dict.

    LMFDB stores Atkin-Lehner data as a list of ``[prime, eigenvalue]``
    pairs (e.g. ``[[11, -1]]``). We convert to a normal Python dict
    ``{prime: ±1}``. Returns ``{}`` if the input is None or empty.
    """
    out: dict[int, int] = {}
    if not eigenvals:
        return out
    for entry in eigenvals:
        if entry is None or len(entry) < 2:
            continue
        try:
            p = int(entry[0])
            v = int(entry[1])
        except (TypeError, ValueError):
            continue
        out[p] = v
    return out

def lookup_polynomial(coeffs: list[int]) -> Optional[dict]:
    """Find a catalog entry matching these ascending coefficients.

    Mahler measure is invariant under the substitution x -> -x, so we
    also try the sign-flipped form.  Returns the first matching entry
    (deep-copied) or ``None``.
    """
    target = _normalize(list(coeffs))
    target_flip = _normalize(_x_flip(target))
    for e in MAHLER_TABLE:
        c = _normalize(list(e["coeffs"]))
        if c == target or c == target_flip:
            return copy.deepcopy(e)
    return None

def lehmer_witness() -> dict:
    """Return Lehmer's degree-10 polynomial entry.

    This is the polynomial conjecturally achieving the global infimum
    M = 1.17628081826... -- Lehmer's conjecture asserts no integer
    polynomial has smaller non-trivial Mahler measure.
    """
    for e in MAHLER_TABLE:
        if e.get("lehmer_witness", False):
            return copy.deepcopy(e)
    raise RuntimeError("Lehmer witness missing from embedded snapshot "
                       "-- this should never happen.")

def degree_minima() -> dict[int, dict]:
    """Map ``degree -> smallest-known Mahler-measure entry`` at each
    degree present in the catalog.

    Only entries flagged ``degree_minimum=True`` are eligible; if
    multiple flagged entries share the same degree (e.g. catalog
    revisions) the one with smallest M wins.
    """
    by_deg: dict[int, dict] = {}
    for e in MAHLER_TABLE:
        if not e.get("degree_minimum", False):
            continue
        d = e["degree"]
        cur = by_deg.get(d)
        if cur is None or e["mahler_measure"] < cur["mahler_measure"]:
            by_deg[d] = copy.deepcopy(e)
    return dict(sorted(by_deg.items()))

def test_edge_tempdir_data_dir_makes_everything_stale(tmp_data_dir):
    """A pristine tmpdir for PROMETHEUS_DATA_DIR ⇒ no caches ⇒ every
    bulk/api source is stale (the embedded ones still aren't).
    """
    for s in F.SOURCE_REGISTRY:
        if s.kind == "embedded" and math.isinf(s.max_staleness_days):
            assert F.is_stale(s) is False
        else:
            # Embedded with finite staleness (mahler) or bulk/api: stale.
            # The embedded mahler file does exist on disk (it's in-tree),
            # so check via cache_path: nonexistent means stale.
            local = F.probe_local(s)
            if not local["exists"]:
