def iter_seeded_survivors(
    *, degree: int = 12, repeat: bool = True,
) -> Iterator[Tuple[List[int], float, str]]:
    """Iterate the curated survivor pool for the given degree.

    Parameters
    ----------
    degree : int
        Polynomial degree to filter by. Default 12 (Lehmer palindromic).
    repeat : bool
        If True (default), the iterator cycles forever — useful for
        interleaving with an unbounded enumerator. If False, iterates
        once.
    """
    if degree == 12:
        pool = get_deg12_survivors()
    else:
        # Future degrees: extend by adding more curated lists.
        pool = []
    if not pool:
        return
    if repeat:
        for entry in cycle(pool):
            yield entry
    else:
        yield from pool

def compute_mahler_measure(coeffs: List[int], dps: int = 60) -> Optional[float]:
    """Compute Mahler measure of a polynomial via mpmath polyroots.

    Returns None on numerical failure (not a substrate-grade evaluator;
    Tier-0's purpose is throughput baselining, not high-precision
    Mahler measurement). Production-grade callers should use
    `prometheus_math._lehmer_brute_force_path_b.mahler_measure_high_precision`
    via sympy factorization.
    """
    try:
        import mpmath
    except ImportError:
        return None
    try:
        # mpmath.polyroots expects coefficients high-degree-first
        mpmath.mp.dps = dps
        roots = mpmath.polyroots(list(coeffs), maxsteps=100)
        # M(p) = |c_lead| * prod over roots r: max(1, |r|)
        c_lead = abs(coeffs[0]) if coeffs[0] != 0 else 1
        M = mpmath.mpf(c_lead)
        for r in roots:
            mag = abs(r)
            if mag > 1:
                M *= mag
        return float(M)
    except Exception:
        return None

def _classify_exception(exc: BaseException) -> str:
    """Returns 'transient' or 'permanent'. Per Aporia Mod 2: HTTP 5xx is
    transient (server side); 4xx is permanent (request shape problem).
    Network timeout / connection-reset is transient. Everything else
    permanent."""
    if isinstance(exc, urllib.error.HTTPError):
        # 5xx server side -> transient; 4xx client side -> permanent
        if 500 <= exc.code < 600:
            return "transient"
        return "permanent"
    if isinstance(exc, _TRANSIENT_EXC_TYPES):
        return "transient"
    return "permanent"

def _t4_m3_rank_bound_check(claim_text: str) -> Optional[Tuple[str, str]]:
    """Bound check for T#4 (R(M<3>) — rank of 3x3 matrix multiplication).

    Catalog: R(M<3>) in [_T4_M3_LOWER, _T4_M3_UPPER] — Landsberg lower
    bound 19; Laderman 1976 upper bound 23. Exact value open.
    """
    m = _M3_RANK_REGEX.search(claim_text)
    if not m:
        return None
    op = m.group(1)
    try:
        val = int(m.group(2))
    except ValueError:
        return None
    if op == "=":
        if val < _T4_M3_LOWER:
            return (
                "decisive_contradicted",
                f"Claim R(M<3>)={val} violates Landsberg lower bound "
                f"R(M<3>) ≥ {_T4_M3_LOWER}.",
            )
        if val > _T4_M3_UPPER:
            return (
                "decisive_contradicted",
                f"Claim R(M<3>)={val} violates Laderman 1976 upper bound "
                f"R(M<3>) ≤ {_T4_M3_UPPER}.",
            )
        return (
            "decisive_inconclusive",
            f"Claim R(M<3>)={val} is within established range "
            f"[{_T4_M3_LOWER}, {_T4_M3_UPPER}] but exact value remains open.",
        )
    if op in ("<=", "<"):
        if val < _T4_M3_LOWER:
            return (
                "decisive_contradicted",
                f"Claim R(M<3>) {op} {val} violates Landsberg lower bound "
                f"R(M<3>) ≥ {_T4_M3_LOWER}.",
            )
        if val >= _T4_M3_UPPER:
            return (
                "decisive_verified",
                f"Claim R(M<3>) {op} {val} is implied by Laderman 1976 upper "
                f"bound R(M<3>) ≤ {_T4_M3_UPPER}.",
            )
        return None
    if op in (">=", ">"):
        if val > _T4_M3_UPPER:
            return (
                "decisive_contradicted",
                f"Claim R(M<3>) {op} {val} violates upper bound R(M<3>) ≤ "
                f"{_T4_M3_UPPER}.",
            )
        if val <= _T4_M3_LOWER:
            return (
                "decisive_verified",
                f"Claim R(M<3>) {op} {val} is implied by Landsberg lower "
                f"bound R(M<3>) ≥ {_T4_M3_LOWER}.",
            )
        return None
    return None

def _verifier_substrate_self_check(claim_payload: dict) -> VerifierResult:
    """substrate_self_check verifier.

    Dispatches via ``verifier_args.invariant_name`` — claim selects a
    named invariant from the registry. Callable returning True is
    decisive_verified; False is decisive_contradicted (the substrate
    is falsifying its own asserted invariant — a real substrate-grade
    catch). Exceptions raised by the callable propagate so the dispatch
    wrapper classifies them as transient/permanent.

    Claims without verifier_args.invariant_name return
    decisive_inconclusive (unable to dispatch).

    Network-free.
    """
    t_start = time.perf_counter()
    args = claim_payload.get("verifier_args", {}) or {}
    invariant_name = args.get("invariant_name")
    invariants = _get_substrate_self_invariants()
    if not isinstance(invariant_name, str) or not invariant_name:
        return VerifierResult(
            outcome_class="decisive_inconclusive",
            method_used="substrate_self_check",
            evidence_blob={
                "reason": "no_invariant_name",
                "available_invariants": sorted(invariants.keys()),
            },
            runtime_ms=int((time.perf_counter() - t_start) * 1000),
            caveats=(
                "substrate_self_check requires verifier_args.invariant_name. "
                "Available invariants are in evidence_blob.available_invariants."
            ),
        )
    if invariant_name not in invariants:
        return VerifierResult(
            outcome_class="decisive_inconclusive",
            method_used="substrate_self_check",
            evidence_blob={
                "reason": "unknown_invariant_name",
                "invariant_name": invariant_name,
                "available_invariants": sorted(invariants.keys()),
            },
            runtime_ms=int((time.perf_counter() - t_start) * 1000),
            caveats=(
                f"Invariant {invariant_name!r} not in substrate-self registry. "
                "Register it via _build_substrate_self_invariants or fix the "
                "claim's verifier_args."
            ),
        )
    holds = invariants[invariant_name]()  # may raise -> dispatch wrapper
    runtime_ms = int((time.perf_counter() - t_start) * 1000)
    if not isinstance(holds, bool):
        return VerifierResult(
            outcome_class="verifier_permanent_failure",
            method_used="substrate_self_check",
            runtime_ms=runtime_ms,
            error_text=(
                f"invariant {invariant_name!r} returned non-bool "
                f"{type(holds).__name__}: {holds!r}"
            ),
        )
    if holds:
        return VerifierResult(
            outcome_class="decisive_verified",
            method_used="substrate_self_check",
            evidence_blob={
                "invariant_name": invariant_name,
                "holds": True,
            },
            runtime_ms=runtime_ms,
        )
    return VerifierResult(
        outcome_class="decisive_contradicted",
        method_used="substrate_self_check",
        evidence_blob={
            "invariant_name": invariant_name,
            "holds": False,
            "reason": "substrate_self_invariant_violated",
        },
        runtime_ms=runtime_ms,
        caveats=(
            f"Substrate-self invariant {invariant_name!r} returned False. "
            "The substrate is falsifying its own asserted invariant — "
            "this is a real substrate-grade catch and requires investigation."
        ),
    )

def stage_claims_to_per_category_jsonl(
    claims: List[dict], out_dir: Path,
) -> Dict[str, int]:
    """Write per-category JSONL files. Returns {category: count} dict."""
    out_dir.mkdir(parents=True, exist_ok=True)
    by_category: Dict[str, List[dict]] = {}
    for c in claims:
        by_category.setdefault(c["claim_category"], []).append(c)
    counts: Dict[str, int] = {}
    # Always write all 5 category files even if empty (consumer contract)
    for cat in ("frontier_survey", "calibration", "boundary", "substrate_self", "other"):
        path = out_dir / f"{cat}.jsonl"
        entries = by_category.get(cat, [])
        with open(path, "w", encoding="utf-8") as f:
            for c in entries:
                f.write(json.dumps(c) + "\n")
        counts[cat] = len(entries)
    return counts

