def test_mi_keys_are_sorted():
    """Pair keys are sorted (a < b) for determinism."""
    corpus = []
    for i in range(15):
        kv = _kv(
            _make_component("naturalizes", triggered=(i % 2 == 0)),
            _make_component("relativizes", triggered=(i % 2 == 0)),
            candidate_hash=f"h{i}",
