def _fast_mahler(coeffs_ascending: list) -> float:
    """Quick Mahler measure for routing/sampling decisions."""
    import numpy as np
    if len(coeffs_ascending) < 2:
        return float("nan")
    roots = np.roots(list(reversed(coeffs_ascending)))
    leading = abs(coeffs_ascending[-1])
    if leading == 0:
        return float("nan")
    prod = float(leading)
    for r in roots:
        if abs(r) > 1.0:
            prod *= abs(r)
    return prod

