def mahler_measure(coeffs_ascending):
    """Compute Mahler measure from ascending coefficient list."""
    coeffs_desc = coeffs_ascending[::-1]
    leading = abs(coeffs_desc[0])
    if leading == 0:
        return float('inf')
    try:
        roots = np.roots(coeffs_desc)
    except Exception:
        return float('inf')
    product = 1.0
    for r in roots:
        mag = abs(r)
        if mag > 1.0:
            product *= mag
    return leading * product

def fetch_measures_by_degree(conn, degree, limit=50000):
    """Fetch polynomial coefficients for a specific degree and compute Mahler measures."""
    cur = conn.cursor()
    # Use random sampling for large degrees
    cur.execute(
        "SELECT coeffs FROM nf_fields WHERE degree = %s ORDER BY random() LIMIT %s",
        (str(degree), limit)
    )
    rows = cur.fetchall()
    cur.close()

    measures = []
    near_lehmer = []  # polynomials with M < 1.5

    for (coeffs_str,) in rows:
        try:
            coeffs = parse_coeffs(coeffs_str)
        except Exception:
            continue

        if is_cyclotomic_approx(coeffs):
            continue

        m = mahler_measure(coeffs)
        if m == float('inf') or np.isnan(m):
            continue

        measures.append(m)
        if m < 1.5:
            near_lehmer.append({
                'mahler_measure': float(m),
                'coeffs': coeffs,
                'degree': degree
            })

    return measures, near_lehmer

def mahler_measure(coeffs_ascending):
    """
    Compute Mahler measure: M(P) = |a_n| * prod(max(1, |root|))
    coeffs_ascending: [a_0, a_1, ..., a_n] where a_n is leading coefficient.
    numpy roots expects descending order.
    """
    # numpy wants highest degree first
    coeffs_desc = coeffs_ascending[::-1]
    leading = abs(coeffs_desc[0])
    if leading == 0:
        return float('inf')

    try:
        roots = np.roots(coeffs_desc)
    except Exception:
        return float('inf')

    product = 1.0
    for r in roots:
        mag = abs(r)
        if mag > 1.0:
            product *= mag

    return leading * product

def is_cyclotomic_approx(coeffs_ascending, tol=1e-8):
    """
    Check if polynomial is cyclotomic: all roots lie on the unit circle.
    Equivalently, Mahler measure == 1 (for monic).
    Also check: must be monic, integer coeffs, and self-reciprocal properties.
    """
    coeffs_desc = coeffs_ascending[::-1]
    if abs(coeffs_desc[0]) != 1:
        return False
    if abs(coeffs_ascending[0]) != 1:
        return False  # constant term must be +/-1 for cyclotomic

    try:
        roots = np.roots(coeffs_desc)
    except Exception:
        return False

    for r in roots:
        if abs(abs(r) - 1.0) > tol:
            return False
    return True

def matches_lehmer_poly(coeffs_ascending):
    """Check if this polynomial is the Lehmer polynomial."""
    if len(coeffs_ascending) != 11:
        return False
    return coeffs_ascending == LEHMER_COEFFS_ASCENDING

def class_number_rank_test(nf_by_degree, ec_cond_to_ranks, n_perms=1000):
    """
    For NF fields whose |disc| matches an EC conductor,
    correlate class_number with EC rank.
    Null: permute the EC rank labels.
    """
    # Collect matched pairs
    matched_cn = []
    matched_rank = []

    for deg in nf_by_degree:
        discs = nf_by_degree[deg]['disc']
        cns = nf_by_degree[deg]['class_number']
        for i in range(len(discs)):
            d = int(discs[i])
            if d in ec_cond_to_ranks:
                for rank in ec_cond_to_ranks[d]:
                    matched_cn.append(int(cns[i]))
                    matched_rank.append(rank)

    if len(matched_cn) < 10:
        return {'n_matched': len(matched_cn), 'status': 'too_few_matches'}

    matched_cn = np.array(matched_cn, dtype=float)
    matched_rank = np.array(matched_rank, dtype=float)

    # Pearson correlation
    real_corr = float(np.corrcoef(matched_cn, matched_rank)[0, 1])

    # Permutation null
    null_corrs = []
    for _ in range(n_perms):
        perm_rank = np.random.permutation(matched_rank)
        null_corrs.append(float(np.corrcoef(matched_cn, perm_rank)[0, 1]))

    null_corrs = np.array(null_corrs)
    z_score = (real_corr - null_corrs.mean()) / null_corrs.std() if null_corrs.std() > 0 else 0.0

    # Also: mean rank by class number bucket
    cn_buckets = {}
    for cn_val in sorted(set(matched_cn.astype(int).tolist())):
        mask = matched_cn == cn_val
        if mask.sum() >= 5:
            cn_buckets[str(cn_val)] = {
                'count': int(mask.sum()),
                'mean_rank': float(matched_rank[mask].mean()),
                'std_rank': float(matched_rank[mask].std()),
            }

    return {
        'n_matched': len(matched_cn),
        'real_correlation': real_corr,
        'null_mean': float(null_corrs.mean()),
        'null_std': float(null_corrs.std()),
        'z_score': float(z_score),
        'p_value_approx': float(np.mean(np.abs(null_corrs) >= np.abs(real_corr))),
        'cn_buckets': cn_buckets,
    }

