def evaluate(self, prompt: str, candidates: List[str]) -> List[Dict]:
    results = []
    scores = []

    # Phase 1: Compute raw falsification scores
    for cand in candidates:
        sc = self._falsification_score(prompt, cand)
        scores.append(sc)

    # Phase 2: Normalize and Rank (Softmax-like scaling for stability)
    if len(scores) > 0:
        min_s = min(scores)
        max_s = max(scores)
        range_s = max_s - min_s if max_s != min_s else 1.0

        # Normalize to 0.1 - 0.9 range to allow confidence differentiation
        normalized_scores = [0.1 + 0.8 * ((s - min_s) / range_s) for s in scores]
    else:
        normalized_scores = [0.5] * len(candidates)

    # Pairwise comparison adjustment (Constraint Propagation)
    # If multiple candidates, boost the one that is most distinct yet consistent
    if len(candidates) > 1:
        avg_score = np.mean(normalized_scores)
        for i, cand in enumerate(candidates):
            # Bonus for being the 'best' of the set relative to average
            if normalized_scores[i] >= avg_score:
                normalized_scores[i] = min(1.0, normalized_scores[i] + 0.05)
            else:
                normalized_scores[i] = max(0.0, normalized_scores[i] - 0.05)

    # Construct result
    for i, cand in enumerate(candidates):
        results.append({
            "candidate": cand,
            "score": float(normalized_scores[i]),
            "reasoning": f"Falsification score based on structural consistency, negation handling, and NCD divergence."
        })

    # Sort descending by score
    results.sort(key=lambda x: x['score'], reverse=True)
    return results

def _mechanism_design_utility(self, prompt_features: Dict, cand_features: Dict, candidate: str) -> float:
    """
    Calculate utility based on incentive compatibility.
    The 'contract' rewards matching structural properties of the prompt.
    """
    utility = 0.0

    # Incentive 1: Negation alignment (Crucial for reasoning)
    if prompt_features['has_negation']:
        if cand_features['has_negation']:
            utility += 1.0 # Reward matching negation
        else:
            utility -= 2.0 # Heavy penalty for ignoring negation (Hallucination)
    else:
        # If prompt has no negation but candidate does, slight penalty for unnecessary complexity
        if cand_features['has_negation']:
            utility -= 0.5

    # Incentive 2: Comparative alignment
    if prompt_features['has_comparative']:
        if cand_features['has_comparative']:
            utility += 1.0
        else:
            utility -= 1.5

    # Incentive 3: Numeric consistency (Simple check)
    if prompt_features['numbers'] and cand_features['numbers']:
        # If both have numbers, reward proximity or presence
        utility += 0.5
    elif prompt_features['numbers'] and not cand_features['numbers']:
        # Prompt asks for math/numbers, candidate ignores -> Penalty
        utility -= 1.0

    return utility

