def _build_graph(self, text: str) -> Tuple[List[str], np.ndarray]:
    """Parse text into nodes and adjacency tensor A [N, N, K]."""
    nodes = self._extract_nodes(text)
    n = len(nodes)
    if n == 0:
        return [], np.zeros((0, 0, len(self.EDGE_TYPES)))

    A = np.zeros((n, n, len(self.EDGE_TYPES)))
    text_lower = text.lower()

    # Detect global modality gains
    g_d = 1.0 + 0.5 * any(m in text_lower for m in self.MODALITY_POSITIVE)
    g_s = 1.0 - 0.5 * any(m in text_lower for m in self.MODALITY_NEGATIVE)

    # Apply gains per edge type logic (simplified broadcast)
    # We apply gains during edge weight assignment

    for rel_type, patterns in self.PATTERNS.items():
        idx = self.TYPE_MAP[rel_type]
        for pattern in patterns:
            if re.search(pattern, text_lower):
                # If relation exists, connect relevant nodes heuristically
                # Since we don't have full dependency parse, we assume dense connectivity 
                # for detected relations in small graphs, weighted by presence
                for i, n1 in enumerate(nodes):
                    for j, n2 in enumerate(nodes):
                        if i != j:
                            # Heuristic: if words appear near the pattern, strengthen link
                            # For robustness in this constrained env, we mark existence
                            weight = 1.0
                            if rel_type == 'negation':
                                weight *= g_s
                            else:
                                weight *= g_d
                            A[i, j, idx] = weight

    return nodes, A

def __init__(self):
    # Logical operators as spectral frequencies
    self.negation_words = {'no', 'not', 'never', 'none', 'neither', 'nobody', 'nothing', 'nowhere', 'deny', 'false', 'wrong'}
    self.comparative_ops = {'>', '<', 'greater', 'less', 'more', 'fewer', 'larger', 'smaller', 'higher', 'lower'}
    self.conditional_ops = {'if', 'then', 'unless', 'otherwise', 'provided', 'assuming'}
    self.boolean_ops = {'and', 'or', 'but', 'however', 'therefore', 'thus', 'hence'}

    # Numeric pattern for extraction
    self.number_pattern = re.compile(r"-?\d+(?:\.\d+)?")

def evaluate(self, prompt, candidates):
    """Rank candidates by ergodic-autopoietic score."""
    # Extract prompt propositions
    prompt_props, prompt_edges = self._extract_propositions(prompt)

    if not prompt_props:
        # Fallback: use NCD
        return self._ncd_fallback(prompt, candidates)

    all_props = set(prompt_props)
    all_edges = list(prompt_edges)

    # Extract candidate propositions
    cand_props_list = []
    for cand in candidates:
        cprops, cedges = self._extract_propositions(cand)
        cand_props_list.append(cprops)
        all_props.update(cprops)
        all_edges.extend(cedges)

    # Build unified graph
    props_list = list(all_props)
    prop_idx = {p: i for i, p in enumerate(props_list)}

    # Convert edges to indices
    indexed_edges = []
    for src, dst, weight in all_edges:
        if src in prop_idx and dst in prop_idx:
            indexed_edges.append((prop_idx[src], prop_idx[dst], weight))

    # Build transition matrix
    T, _ = self._build_transition_matrix(props_list, all_edges)

    # Seed from prompt propositions
    seed_indices = {prop_idx[p] for p in prompt_props if p in prop_idx}

    # Ergodic propagation
    stationary = self._ergodic_propagation(T, seed_indices, len(props_list))

    # Autopoietic closure
    closure_set = self._autopoietic_closure(indexed_edges, seed_indices, len(props_list))

    # Score candidates
    results = []
    for cand, cprops in zip(candidates, cand_props_list):
        if not cprops:
            score = 0.0
        else:
            # Average stationary truth of propositions in closure
            valid_props = [prop_idx[p] for p in cprops if p in prop_idx and prop_idx[p] in closure_set]
            if valid_props:
                score = np.mean([stationary[i] for i in valid_props])
            else:
                score = 0.0

        # Add small NCD bonus (max 10%)
        ncd_score = self._ncd(prompt, cand)
        final_score = 0.9 * score + 0.1 * (1.0 - ncd_score)

        results.append({
            'candidate': cand,
            'score': float(final_score),
            'reasoning': f'Ergodic truth: {score:.3f}, closure size: {len(closure_set)}'
        })

    return sorted(results, key=lambda x: x['score'], reverse=True)

def evaluate(self, prompt, candidates):
    """Evaluate and rank candidates"""
    results = []

    # Parse prompt
    p_nums = self._parse_numbers(prompt)
    triples = self._extract_triples(prompt)
    gain = self._compute_gain(prompt)
    A, node_idx, _ = self._build_graph(triples, gain)
    C = self._transitive_closure(A) if len(A) > 0 else np.array([])

    for cand in candidates:
        score = 0.0
        reasons = []

        # Numeric comparison (30%)
        c_nums = self._parse_numbers(cand)
        if len(p_nums) >= 2 and c_nums:
            if 'greater' in prompt.lower() or 'more' in prompt.lower():
                if abs(c_nums[0] - max(p_nums)) < 0.01:
                    score += 0.3
                    reasons.append('numeric_max_match')
            elif 'less' in prompt.lower() or 'fewer' in prompt.lower():
                if abs(c_nums[0] - min(p_nums)) < 0.01:
                    score += 0.3
                    reasons.append('numeric_min_match')

        # Arithmetic evaluation (30%)
        if any(op in prompt for op in ['+', '-', '*', '/']):
            result = self._evaluate_arithmetic(prompt)
            if result is not None and c_nums and abs(c_nums[0] - result) < 0.01:
                score += 0.3
                reasons.append('arithmetic_match')

        # Graph-based constraint satisfaction (40%)
        if len(C) > 0:
            c_triples = self._extract_triples(cand)
            if c_triples:
                sat = sum(1 for s, r, o in c_triples 
                         if s in node_idx and o in node_idx and C[node_idx[s], node_idx[o]] > 0.3)
                viol = sum(1 for s, r, o in c_triples 
                          if s in node_idx and o in node_idx and r == 'neg' and C[node_idx[s], node_idx[o]] > 0.3)
                utility = sat - 2 * viol
                score += 0.4 * max(0, utility / max(1, len(c_triples)))
                reasons.append(f'constraint_sat={sat}_viol={viol}')

        # NCD tiebreaker (10%)
        ncd = self._ncd(prompt, cand)
        score += 0.1 * (1 - ncd)

        results.append({
            'candidate': cand,
            'score': min(1.0, score),
            'reasoning': '; '.join(reasons) if reasons else 'ncd_only'
        })

    return sorted(results, key=lambda x: x['score'], reverse=True)

def _spectral_radius(self, W: np.ndarray) -> float:
    """Compute spectral radius (largest eigenvalue magnitude)."""
    try:
        eigvals = np.linalg.eigvals(W)
        return np.max(np.abs(eigvals))
    except:
        return 1.0

def _build_graph(triples: List[Tuple]) -> Tuple[List[str], np.ndarray, List[str]]:
    """Builds adjacency tensor and node list from triples."""
    nodes = list(set([t[0] for t in triples] + [t[2] for t in triples]))
    node_map = {n: i for i, n in enumerate(nodes)}
    n = len(nodes)

    # Relation types mapping
    rel_types = ['NEG', 'CMP', 'COND', 'CAUS', 'EQ', 'GEN', 'NUM_CMP']
    r = len(rel_types)

    # Adjacency tensor A[i, j, k] = 1 if edge i->j has relation k
    A = np.zeros((n, n, r), dtype=np.float32)

    for s, p, o, r_type in triples:
        if s in node_map and o in node_map:
            i, j = node_map[s], node_map[o]
            try:
                k = rel_types.index(r_type)
                A[i, j, k] = 1.0
            except ValueError:
                A[i, j, rel_types.index('GEN')] = 1.0

    # Node features (one-hot for predicate types present on outgoing edges)
    # Simplified: count outgoing relation types
    X = np.zeros((n, r), dtype=np.float32)
    for i in range(n):
        # Sum over outgoing edges and relation types
        outgoing = A[i, :, :]
        if outgoing.sum() > 0:
            # Normalize to get feature vector
            X[i, :] = outgoing.sum(axis=0)
            if X[i, :].sum() > 0:
                X[i, :] /= X[i, :].sum()

    return nodes, A, X, rel_types

def _spectral_score(self, matrix: np.ndarray) -> float:
    """Compute the dominant eigenvalue (spectral radius) as the validity score."""
    try:
        eigenvalues = np.linalg.eigvals(matrix)
        # Spectral radius: max absolute eigenvalue
        return float(np.max(np.abs(eigenvalues)))
    except np.linalg.LinAlgError:
        return 0.0

