        final_score = 0.70 * fmps + 0.15 * ncd + 0.15 * len_score

        results.append({
            "candidate": cand,
            "score": final_score,
            "reasoning": f"FMPS={fmps:.2f}, NCD={ncd:.2f}, len={len_score:.2f}"
        })

