def _compute_spectral_gap(self, A: np.ndarray) -> float:
    """Compute Laplacian spectral gap."""
    n = A.shape[0]
    if n <= 1:
        return 0.0

    D = np.diag(A.sum(axis=1))
    L = D - A

    # Eigenvalues (sorted)
    try:
        eigvals = np.linalg.eigvalsh(L)
    except np.linalg.LinAlgError:
        return 0.0

    # Gamma = lambda_1 (second smallest)
    gamma = eigvals[1] if len(eigvals) > 1 else 0.0
    return float(gamma)

def _compute_spectral_score(self, F: np.ndarray) -> float:
    """Compute SEMS score using spectral analysis + metamorphic constraints"""
    if F.shape[0] < 2:
        return 0.5

    n, m = F.shape
    e = np.zeros(m, dtype=np.float32)

    # Spectral step: compute power spectrum for each feature
    power_spectra = []
    for i in range(m):
        if F[:, i].sum() == 0:
            power_spectra.append(0.0)
        else:
            fft = np.fft.rfft(F[:, i].astype(np.float32))
            power = np.abs(fft) ** 2
            power_spectra.append(np.max(power) if len(power) > 0 else 0.0)

    P = np.array(power_spectra)

    # Constraint propagation via metamorphic edges
    for _ in range(5):
        for i, j, w in self.metamorphic_edges:
            if i < m and j < m:
                violation = w * abs(P[i] - P[j])
                e[j] += violation

    # Score: inverse of inconsistency norm
    score = 1.0 / (1.0 + np.linalg.norm(e))
    return float(score)

def _compute_spectral_signal(self, A: np.ndarray) -> np.ndarray:
    """Compute Power Spectral Density of the graph Laplacian."""
    if A.shape[0] == 0:
        return np.array([0.0])

    D = np.diag(A.sum(axis=1))
    L = D - A

    # Eigenvalues
    try:
        eigenvalues = np.linalg.eigvalsh(L)
    except np.linalg.LinAlgError:
        eigenvalues = np.zeros(A.shape[0])

    # Welch's method approximation (simplified for single segment due to size constraints)
    # Pad to power of 2 for FFT efficiency
    n = len(eigenvalues)
    if n == 0: return np.array([0.0])

    fft_val = np.fft.rfft(eigenvalues)
    psd = np.abs(fft_val)**2
    return psd

