def evaluate(self, prompt, candidates):
    """Rank candidates by MaxEnt energy + susceptibility + falsification."""
    prompt_literals = self._parse_literals(prompt)
    prompt_numbers = self._extract_numbers(prompt)

    results = []

    for candidate in candidates:
        cand_literals = self._parse_literals(candidate)
        cand_numbers = self._extract_numbers(candidate)

        # Numeric comparison (constructive computation)
        numeric_match = 0.0
        if prompt_numbers and cand_numbers:
            if any(re.search(r'\b(greater|more|larger)\b', prompt.lower())):
                if cand_numbers and prompt_numbers and cand_numbers[0] > prompt_numbers[-1]:
                    numeric_match = 1.0
            elif any(re.search(r'\b(less|fewer|smaller)\b', prompt.lower())):
                if cand_numbers and prompt_numbers and cand_numbers[0] < prompt_numbers[-1]:
                    numeric_match = 1.0
            else:
                numeric_match = 1.0 if set(prompt_numbers) & set(cand_numbers) else 0.0

        # Build constraint matrix
        C, b = self._build_constraint_matrix(prompt_literals, cand_literals)

        if C.shape[0] > 0 and C.shape[1] > 0:
            lambda_vec = self._maxent_inference(C, b)
            x_cand = np.array([1.0 if any(cl[0] == pl[0] for pl in prompt_literals) else 0.0 
                               for cl in (cand_literals or [0])]) 
            if len(x_cand) == 0:
                x_cand = np.array([0.5] * C.shape[1])
            elif len(x_cand) < C.shape[1]:
                x_cand = np.pad(x_cand, (0, C.shape[1] - len(x_cand)), constant_values=0.5)
            else:
                x_cand = x_cand[:C.shape[1]]

            E = self._compute_energy(lambda_vec, C, x_cand)
            chi = self._compute_susceptibility(lambda_vec, C, x_cand)
            F = self._falsification_score(lambda_vec, C, x_cand)
        else:
            E, chi, F = 0.0, 0.0, 0.0

        # NCD tiebreaker (max 15%)
        ncd = self._compute_ncd(prompt, candidate)
        ncd_score = 1 - ncd

        # Structural score (60%), numeric (25%), NCD (15%)
        score = 0.6 * (-E - self.alpha * chi - self.beta * F) + 0.25 * numeric_match + 0.15 * ncd_score

        reasoning = f"E={E:.2f}, chi={chi:.2f}, F={F}, num={numeric_match:.2f}, ncd={ncd:.2f}"
        results.append({"candidate": candidate, "score": score, "reasoning": reasoning})

    results.sort(key=lambda x: x["score"], reverse=True)
    return results

def _get_order_parameter(self, W):
    """Computes the largest eigenvalue magnitude (phase transition indicator)."""
    if W.size == 0:
        return 0.0
    try:
        eigvals = np.linalg.eigvals(W)
        return float(np.max(np.abs(eigvals)))
    except np.linalg.LinAlgError:
        return 0.0

def _phase_transition_score(self, J: np.ndarray) -> float:
    """
    Estimates distance to criticality using spectral radius.
    Closer to lambda_max = 1 implies higher sensitivity (criticality).
    """
    if J.size == 0:
        return 0.0
    try:
        eigenvalues = np.linalg.eigvals(J)
        lambda_max = np.max(np.abs(eigenvalues))
        # Distance to critical point (lambda = 1)
        delta = np.abs(lambda_max - 1.0)
        # Score: closer to 1 is better (lower delta), but avoid division by zero
        return 1.0 / (1.0 + delta)
    except:
        return 0.0

def _parse_graph(self, text: str) -> Tuple[List[str], np.ndarray]:
    """
    Parse text into nodes and an adjacency tensor A[i, j, r].
    Returns (nodes, tensor).
    """
    nodes = self._extract_terms(text)
    n = len(nodes)
    if n == 0:
        return [], np.array([])

    R = len(self.relations)
    A = np.zeros((n, n, R), dtype=float)
    text_lower = text.lower()

    # Helper to find node indices
    def get_idx(term):
        try: return nodes.index(term)
        except ValueError: return -1

    # 1. Negations
    neg_patterns = [r"not\s+(\w+)", r"no\s+(\w+)", r"never\s+(\w+)", r"false"]
    for pat in neg_patterns:
        for m in re.finditer(pat, text_lower):
            target = m.group(1) if len(m.groups()) > 0 else m.group(0)
            t_idx = get_idx(target)
            if t_idx != -1:
                # Connect previous word or self to negation
                A[t_idx, t_idx, self.relations.index('neg')] = 1.0

    # 2. Comparatives (Greater/Less)
    if "greater" in text_lower or ">" in text_lower or "more" in text_lower:
        # Simplified: mark all number pairs as cmp
        nums = [i for i, x in enumerate(nodes) if x.replace('.','').isdigit()]
        for i in nums:
            for j in nums:
                if i != j:
                    A[i, j, self.relations.index('cmp')] = 1.0

    if "less" in text_lower or "<" in text_lower:
        nums = [i for i, x in enumerate(nodes) if x.replace('.','').isdigit()]
        for i in nums:
            for j in nums:
                if i != j:
                    A[i, j, self.relations.index('cmp')] = -1.0 # Directionality

    # 3. Conditionals (if -> then)
    if "if" in text_lower:
        # Rough heuristic: words before 'if' condition, after consequence
        parts = re.split(r'\bif\b', text_lower, maxsplit=1)
        if len(parts) == 2:
            antecedent_terms = self._extract_terms(parts[0])
            consequent_terms = self._extract_terms(parts[1])
            for t1 in antecedent_terms:
                for t2 in consequent_terms:
                    i, j = get_idx(t1), get_idx(t2)
                    if i != -1 and j != -1:
                        A[i, j, self.relations.index('cond')] = 1.0

    # 4. Causal (because, causes)
    causal_words = ['because', 'causes', 'leads', 'results']
    for cw in causal_words:
        if cw in text_lower:
            # Mark relations around the word
            idx = text_lower.find(cw)
            # Simple proximity logic
            for i, n1 in enumerate(nodes):
                for j, n2 in enumerate(nodes):
                    if i != j:
                        A[i, j, self.relations.index('cause')] = 0.5

    # 5. Numeric Value Consistency (Node attribute simulation via self-loop weight)
    for i, term in enumerate(nodes):
        if re.match(r'\d+\.?\d*', term):
            val = float(term)
            # Encode magnitude in a specific slice or just flag presence
            A[i, i, 0] = np.sign(val) # Use first relation slice for sign/magnitude hint

    return nodes, A

