def _parse_sentence(self, text: str) -> np.ndarray:
    """Extract binary features for the 6 predicates."""
    text_lower = text.lower()
    features = np.zeros(6)
    for i, key in enumerate(self.PREDICATES):
        for pattern in self.PATTERNS[key]:
            if re.search(pattern, text_lower):
                features[i] = 1.0
                break
    # Normalize numeric if specific value found (simplified to presence for this tensor slot)
    return features

def confidence(self, prompt: str, answer: str) -> float:
    """
    Estimates confidence based on the 'rank' of the reasoning required.
    High complexity prompts with structurally consistent answers yield high confidence.
    """
    prompt_feats = self._extract_structural_features(prompt)
    cand_feats = self._extract_structural_features(answer)

    # Base confidence
    conf = 0.5

    # Adjust based on structural match
    if prompt_feats['has_negation'] == cand_feats['has_negation']:
        conf += 0.2
    if prompt_feats['has_comparative'] == cand_feats['has_comparative']:
        conf += 0.15
    if prompt_feats['has_conditional'] == cand_feats['has_conditional']:
        conf += 0.15

    # Penalty for length mismatch in complex prompts
    if len(prompt_feats['numbers']) > 0:
        if len(cand_feats['numbers']) > 0:
            conf += 0.2
        else:
            conf -= 0.3

    return max(0.0, min(1.0, conf))

def _build_tensor(self, triples: List[Tuple[str, str, str]]) -> np.ndarray:
    """Builds a 3rd-order tensor X [Subject, Relation, Object]."""
    if not triples:
        return np.zeros((1, 1, 1))

    subjects = list(set(t[0] for t in triples))
    relations = list(set(t[1] for t in triples))
    objects = list(set(t[2] for t in triples))

    s_map = {s: i for i, s in enumerate(subjects)}
    r_map = {r: i for i, r in enumerate(relations)}
    o_map = {o: i for i, o in enumerate(objects)}

    I, J, K = len(subjects), len(relations), len(objects)
    # Ensure minimum dimensions for SVD
    I, J, K = max(I, 2), max(J, 2), max(K, 2)

    X = np.zeros((I, J, K))

    for s, r, o in triples:
        si = s_map.get(s, 0) % I
        ri = r_map.get(r, 0) % J
        oi = o_map.get(o, 0) % K
        X[si, ri, oi] = 1.0

    return X

def _semantic_tensor(self, prompt: str, candidates: List[str]) -> np.ndarray:
    """Synthesizes a high-order tensor from string hashes to simulate feature mapping."""
    if not candidates:
        return np.array([])

    # Deterministic pseudo-embedding using char codes and positions
    def embed(s: str, dim: int) -> np.ndarray:
        vec = np.zeros(dim)
        for i, c in enumerate(s):
            vec[i % dim] += (ord(c) - 32) / 128.0 * np.exp(-0.1 * i)
        norm = np.linalg.norm(vec)
        return vec / (norm + self.eps)

    n_cand = len(candidates)
    # Dimensions: [Prompt_Features, Candidate_Index, Candidate_Features]
    # We simulate a 3rd order tensor H_{i, j, k}
    dim_p, dim_c = 16, 16
    p_vec = embed(prompt, dim_p)

    tensor = np.zeros((dim_p, n_cand, dim_c))
    for j, cand in enumerate(candidates):
        c_vec = embed(cand, dim_c)
        # Outer product interaction
        tensor[:, j, :] = np.outer(p_vec, c_vec).reshape(dim_p, dim_c)[:, 0] # Simplified interaction
        # Actually, let's make it a true interaction matrix for the candidate
        tensor[:, j, :] = np.dot(p_vec[:, None], c_vec[None, :]) * (j + 1) / n_cand

    return tensor

def confidence(self, prompt: str, answer: str) -> float:
    # Evaluate the single answer against itself to check internal consistency
    res = self.evaluate(prompt, [answer])
    if not res:
        return 0.0
    # Confidence is derived from the stability score of the single-candidate tensor
    # In a single candidate scenario, variance is low if the representation is robust
    return max(0.0, min(1.0, res[0]['score']))

def _build_tensor(self, sentences: List[str], max_sents: int = 5) -> np.ndarray:
    """Builds a 2D tensor X (N x D) from sentences, padding if necessary."""
    D = 8 # Fixed feature dimension
    N = min(len(sentences), max_sents)
    if N == 0:
        return np.zeros((1, D))

    X = np.zeros((max_sents, D))
    for i, sent in enumerate(sentences[:max_sents]):
        feats = self._extract_features(sent)
        # Ensure length matches D
        if len(feats) < D:
            feats += [0.0] * (D - len(feats))
        X[i, :] = feats[:D]
    return X

def evaluate(self, prompt: str, candidates: List[str]) -> List[Dict]:
    if not candidates:
        return []

    results = []
    for cand in candidates:
        # Type Check
        if not self._type_check(cand):
            score = 0.0
            reason = "Rejected: Ill-typed hypothesis (fails symmetry/shape constraints)."
        else:
            # Encode & Decompose
            tensor = self._encode_to_tensor(cand)
            k_complexity = self._decompose_and_compress(tensor)

            # Score inversely proportional to complexity (Occam's Razor)
            # Normalized roughly to 0-1 range assuming typical complexity values
            score = 1.0 / (1.0 + k_complexity / 10.0)
            reason = f"Accepted. Normal form rank: {int(np.log1p(np.var(tensor))*2)}, K(T)≈{k_complexity:.2f}. Simpler representations favored."

        results.append({
            "candidate": cand,
            "score": score,
            "reasoning": reason
        })

    # Rank by score descending
    return sorted(results, key=lambda x: x["score"], reverse=True)

def confidence(self, prompt: str, answer: str) -> float:
    """Returns confidence based on type validity and compression efficiency."""
    if not self._type_check(answer):
        return 0.0

    tensor = self._encode_to_tensor(answer)
    k_val = self._decompose_and_compress(tensor)

    # Map complexity to confidence: Low K -> High Confidence
    # Using a sigmoid-like mapping for smoothness
    confidence = 1.0 / (1.0 + np.exp((k_val - 5.0) / 2.0))
    return float(np.clip(confidence, 0.01, 0.99))

def _extract_structure(self, text: str) -> Dict[str, any]:
    """Extracts structural features acting as low-rank tensor slices."""
    features = {}
    text_lower = text.lower()

    # Boolean flags for logical operators
    for key, pattern in self.patterns.items():
        if key != 'numeric':
            features[key] = bool(pattern.search(text))

    # Numeric extraction and evaluation
    nums = self.patterns['numeric'].findall(text)
    features['numeric_count'] = len(nums)
    features['numeric_vals'] = [float(n) for n in nums] if nums else []

    # Simple numeric logic check (e.g., is 9.11 < 9.9?)
    features['numeric_sorted'] = True
    if len(features['numeric_vals']) > 1:
        # Check if numbers appear in sorted order (heuristic for consistency)
        is_sorted = all(features['numeric_vals'][i] <= features['numeric_vals'][i+1] 
                        for i in range(len(features['numeric_vals'])-1))
        features['numeric_sorted'] = is_sorted

    return features

def _hash_word(self, word: str) -> int:
    """Simple hash to map words to tensor indices."""
    return hash(word.lower()) % self.vocab_size

