def _pick_field_and_value(row: dict) -> Optional[tuple[str, float, str]]:
    """Find a numeric payload field for which a tightening ladder
    exists. Returns (field_name, observed_value, ladder_name) or None."""
    extras = row.get("extras", {}) or {}
    payload = extras.get("composition_payload", {}) or {}
    candidates: list[tuple[str, float, str]] = []
    # Sources to scan: payload, top-level kill_vector, claim_payload
    sources = [payload, row.get("kill_vector") or {}, row.get("claim_payload") or {}]
    for src in sources:
        if not isinstance(src, dict):
            continue
        for k, v in src.items():
            if isinstance(v, bool):
                continue
            if not isinstance(v, (int, float)):
                continue
            ladder_name = FIELD_TO_LADDER.get(k)
            if ladder_name is None:
                continue
            candidates.append((k, float(v), ladder_name))
    if not candidates:
        return None
    # Pick the field with highest absolute magnitude (proxy: "most
    # bound-able" — closest to a real threshold)
    return max(candidates, key=lambda t: abs(t[1]))

def find_strongest_predicate(text: str) -> Optional[PredicateTier]:
    """Scan text for any registered predicate; return the highest-rank
    one detected (or None if none matched)."""
    text_lower = (text or "").lower()
    matched: list[PredicateTier] = []
    for tier in PREDICATE_LATTICE:
        if re.search(tier.detection_regex, text_lower):
            matched.append(tier)
    if not matched:
        return None
    return max(matched, key=lambda t: t.rank)

def find_weakest_predicate(text: str) -> Optional[PredicateTier]:
    """Inverse of find_strongest -- used by G14 to find which predicate
    to strengthen."""
    text_lower = (text or "").lower()
    matched: list[PredicateTier] = []
    for tier in PREDICATE_LATTICE:
        if re.search(tier.detection_regex, text_lower):
            matched.append(tier)
    if not matched:
        return None
    return min(matched, key=lambda t: t.rank)

def tier_below(tier: PredicateTier) -> Optional[PredicateTier]:
    """Return the tier one rank weaker than `tier` (G13 step). None if
    `tier` is already at rank 1."""
    for t in PREDICATE_LATTICE:
        if t.rank == tier.rank - 1:
            return t
    return None

def tier_above(tier: PredicateTier) -> Optional[PredicateTier]:
    """Return the tier one rank stronger than `tier` (G14 step). None
    if `tier` is already at the top rank."""
    for t in PREDICATE_LATTICE:
        if t.rank == tier.rank + 1:
            return t
    return None

