def find_strictest_arith(text: str) -> Optional[dict]:
    """Scan text for arithmetic operators; return the highest-rank
    one detected. None if no match."""
    text_lower = (text or "").lower()
    matched = []
    for tier in ARITHMETIC_LADDER:
        if re.search(tier["regex"], text_lower):
            matched.append(tier)
    if not matched:
        return None
    return max(matched, key=lambda t: t["rank"])

def arith_below(tier: dict) -> Optional[dict]:
    """Return the tier one rank weaker, or None if at bottom."""
    target_rank = tier["rank"] - 1
    for t in ARITHMETIC_LADDER:
        if t["rank"] == target_rank:
            return t
    return None

def _pick_field_and_value(row: dict) -> Optional[tuple[str, float, str]]:
    """Find a numeric payload field for which a tightening ladder
    exists. Returns (field_name, observed_value, ladder_name) or None."""
    extras = row.get("extras", {}) or {}
    payload = extras.get("composition_payload", {}) or {}
    candidates: list[tuple[str, float, str]] = []
    # Sources to scan: payload, top-level kill_vector, claim_payload
    sources = [payload, row.get("kill_vector") or {}, row.get("claim_payload") or {}]
    for src in sources:
        if not isinstance(src, dict):
            continue
        for k, v in src.items():
            if isinstance(v, bool):
                continue
            if not isinstance(v, (int, float)):
                continue
            ladder_name = FIELD_TO_LADDER.get(k)
            if ladder_name is None:
                continue
            candidates.append((k, float(v), ladder_name))
    if not candidates:
        return None
    # Pick the field with highest absolute magnitude (proxy: "most
    # bound-able" — closest to a real threshold)
    return max(candidates, key=lambda t: abs(t[1]))

def _is_borderline_scalar(row: dict) -> bool:
    """Borderline = weak-positive signal worth lifting. POSSIBLE /
    UNVERIFIED verdicts qualify. Pollux rows with |corr_raw| in
    [0.30, 0.70] qualify."""
    verdict = (row.get("verdict") or "").upper()
    if verdict in {"POSSIBLE", "UNVERIFIED"}:
        return True
    kv = row.get("kill_vector") or {}
    overall_tier = ((kv.get("overall") or {}).get("verdict") or "").upper()
    if overall_tier in {"POSSIBLE", "UNVERIFIED", "MARGINAL"}:
        return True
    corr_raw = kv.get("corr_raw")
    if isinstance(corr_raw, (int, float)):
        if 0.30 <= abs(corr_raw) <= 0.70:
            return True
    return False

def _find_correlation_field(row: dict) -> Optional[tuple[str, float]]:
    extras = row.get("extras", {}) or {}
    sources = [
        extras.get("composition_payload", {}) or {},
        row.get("kill_vector", {}) if isinstance(row.get("kill_vector"), dict) else {},
        row.get("claim_payload", {}) or {},
    ]
    for src in sources:
        for k, v in src.items():
            if isinstance(v, bool):
                continue
            if not isinstance(v, (int, float)):
                continue
            if k in CORRELATION_FIELDS and abs(v) > DECOUPLING_THRESHOLD:
                return (k, float(v))
    return None

def _battery_signature(row: dict) -> Optional[str]:
    """Extract a battery-shape signature: shared kill_pattern, or
    kill_vector overall.tier. Returns None if no signature available."""
    kp = row.get("kill_pattern")
    if kp:
        return f"kp:{kp}"
    kv = row.get("kill_vector") or {}
    overall = (kv.get("overall") or {})
    tier = overall.get("tier")
    if tier:
        return f"tier:{tier}"
    return None

def _parent_pool(self, state: SwarmState) -> list[dict]:
    """G24 needs a Mahler-context parent. Search Stygian +
    Erebos ledgers for any claim referencing Mahler / Lehmer /
    Salem / BL-C-00[134]."""
    out = []
    for r in (list(state.stygian_substantive) + list(state.erebos_self_ledger)):
        if self._has_mahler_context(r.get("canonical_claim_text", "")):
            out.append(r)
    return out

def find_strongest_predicate(text: str) -> Optional[PredicateTier]:
    """Scan text for any registered predicate; return the highest-rank
    one detected (or None if none matched)."""
    text_lower = (text or "").lower()
    matched: list[PredicateTier] = []
    for tier in PREDICATE_LATTICE:
        if re.search(tier.detection_regex, text_lower):
            matched.append(tier)
    if not matched:
        return None
    return max(matched, key=lambda t: t.rank)

def find_weakest_predicate(text: str) -> Optional[PredicateTier]:
    """Inverse of find_strongest -- used by G14 to find which predicate
    to strengthen."""
    text_lower = (text or "").lower()
    matched: list[PredicateTier] = []
    for tier in PREDICATE_LATTICE:
        if re.search(tier.detection_regex, text_lower):
            matched.append(tier)
    if not matched:
        return None
    return min(matched, key=lambda t: t.rank)

def tier_below(tier: PredicateTier) -> Optional[PredicateTier]:
    """Return the tier one rank weaker than `tier` (G13 step). None if
    `tier` is already at rank 1."""
    for t in PREDICATE_LATTICE:
        if t.rank == tier.rank - 1:
            return t
    return None

def tier_above(tier: PredicateTier) -> Optional[PredicateTier]:
    """Return the tier one rank stronger than `tier` (G14 step). None
    if `tier` is already at the top rank."""
    for t in PREDICATE_LATTICE:
        if t.rank == tier.rank + 1:
            return t
    return None

