def _load_mossinghoff_partition() -> Optional[dict]:
    try:
        from prometheus_math.databases.mahler import all_below
    except Exception:
        return None
    entries = all_below(2.0)
    salem: list[float] = []
    non_salem: list[float] = []
    for e in entries:
        m = e.get("mahler_measure")
        if m is None or m <= 1.0 + 1e-9:
            continue
        if bool(e.get("salem_class")):
            salem.append(float(m))
        else:
            non_salem.append(float(m))
    if not salem or not non_salem:
        return None
    return {"salem": salem, "non_salem": non_salem}

def applicable(self, queue_payload: dict) -> bool:
    if queue_payload.get("source") != "erebos":
        return False
    plugin_id = queue_payload.get("erebos_plugin_id")
    if plugin_id != "g04_survivor_tightening":
        return False
    composed_id = queue_payload.get("erebos_composed_id", "") or ""
    # Match: G04 emission whose parent is a G02 Salem-Lehmer
    # composition AT THE FULL-CATALOG SCOPE (no specific band
    # marker). Newer band-restricted loaders (e.g.,
    # lehmer_band_1_30_to_1_50) handle their own variants and
    # should not be intercepted by this generic-tightening loader.
    if "lehmer_band_" in composed_id:
        return False  # let band-specific loader handle
    return "BL-C-001" in composed_id or "salem" in composed_id.lower()

def _load_mossinghoff_partition() -> Optional[dict]:
    """Load Mossinghoff catalog; partition entries by salem_class.
    Returns dict with keys 'salem' (M values list) and 'non_salem'
    (M values list), or None on failure."""
    try:
        from prometheus_math.databases.mahler import all_below
    except Exception:
        return None
    entries = all_below(2.0)
    salem: list[float] = []
    non_salem: list[float] = []
    for e in entries:
        m = e.get("mahler_measure")
        if m is None or m <= 1.0 + 1e-9:
            continue  # exclude cyclotomic floor
        if bool(e.get("salem_class")):
            salem.append(float(m))
        else:
            non_salem.append(float(m))
    if not salem or not non_salem:
        return None
    return {"salem": salem, "non_salem": non_salem}

