def score_candidate(self, node: Dict[str, Any]) -> float:
    """Predict candidate quality (mean battery_survival proxy) for a single
    candidate step. Higher = more likely to be a good move.

    Pre-validated: 47.25% rank-1 selection in 4-way candidate ranking on
    walk_1 (+22pp over random) per Z3_UTILITY_PROXY_2026-05-26.md.
    """
    feat21 = np.array(_no_battery_features(node), dtype=np.float64)
    if self.prm_v0.w.shape[0] == 22:  # 21 + bias (leak-free)
        return float(feat21 @ self.prm_v0.w[:-1] + self.prm_v0.w[-1])
    else:
        # PRM was trained on 33-dim feature set (with battery)
        feat33 = np.array(extract_step_features(node), dtype=np.float64).reshape(1, -1)
        return float(self.prm_v0.predict(feat33)[0])

def load_kind_distributions():
    """Per-kind kill_vector mean distributions from walk_1, for quartile thresholds."""
    by_kind = defaultdict(list)
    for jf in sorted(WALK_1_GLOB.glob("records_*.jsonl")):
        with open(jf, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line: continue
                r = json.loads(line)
                for s in r.get("decomposition") or []:
                    for sib in s.get("counterfactual_siblings") or []:
                        kind = sib.get("sibling_kind")
                        kv = sib.get("sibling_kill_vector") or []
                        if kind and kv:
                            by_kind[kind].append(float(np.mean(kv)))
    return {kind: np.array(vs) for kind, vs in by_kind.items()}

