def _extract_domain(row: dict) -> str:
    cp = row.get("claim_payload") or {}
    if not isinstance(cp, dict):
        return "unknown"
    pid = cp.get("problem_id", "")
    if isinstance(pid, str) and pid.startswith("BL-C"):
        return "mahler"
    if isinstance(pid, str) and pid.startswith("BL-A"):
        return "analytic"
    return "unknown"

def _build_features(row: dict, *, raw: bool) -> tuple:
    plugin = _extract_plugin(row) or "?"
    kp = row.get("kill_pattern") or "PROMOTED"
    domain = _extract_domain(row)
    if not raw:
        return (plugin, kp, domain)
    # Raw adds three structural features the seam doesn't carry
    payload_sig = _payload_signature(row)
    method = row.get("method") or "none"
    has_kv = bool(row.get("kill_vector"))
    return (plugin, kp, domain, payload_sig, method, has_kv)

def _classify_slope_ci(rank: int, slope: float, lo: float, hi: float) -> tuple[str, str]:
    if lo > 0:
        return "PROMOTED", f"bsd_regulator_grows_with_conductor_rank{rank}"
    if hi < 0:
        return "REJECTED", f"bsd_regulator_shrinks_with_conductor_rank{rank}"
    return "REJECTED", f"bsd_regulator_independent_of_conductor_rank{rank}"

def applicable(self, queue_payload: dict) -> bool:
    if queue_payload.get("source") != "erebos":
        return False
    if queue_payload.get("erebos_plugin_id") != "g23_asymptotic_limit":
        return False
    composed_id = queue_payload.get("erebos_composed_id", "") or ""
    return (
        "bsd" in composed_id.lower()
        and "rank" in composed_id.lower()
    )

def load_bsd_entries() -> list[dict]:
    """Load all entries from bsd_rich.json.gz. Cached.

    Each entry has 'base' (label, ainvs, conductor, a_p, rank) and
    'rich' (regulator, real_period, L1, ...). Returns the list of
    'entries' from the top-level dict, or [] on load failure.
    """
    if not BSD_DB_PATH.exists():
        return []
    try:
        with gzip.open(BSD_DB_PATH) as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError):
        return []
    return data.get("entries", [])

